// Generated by bynkc — do not edit by hand.
// bynk runtime — shared by every emitted module.

export type Result<T, E> =
  | { readonly tag: "Ok"; readonly value: T }
  | { readonly tag: "Err"; readonly error: E };

export const Ok = <T>(value: T): Result<T, never> => ({ tag: "Ok", value });
export const Err = <E>(error: E): Result<never, E> => ({ tag: "Err", error });

export type Option<T> =
  | { readonly tag: "Some"; readonly value: T }
  | { readonly tag: "None" };

export const Some = <T>(value: T): Option<T> => ({ tag: "Some", value });
export const None: Option<never> = { tag: "None" };

// v0.110 (ADR 0142): the `Bytes` primitive runtime. A `Bytes` erases to a
// `Uint8Array` (an immutable finite octet sequence at the Bynk level), so
// unlike the number-erased base types its equality is by content, not host
// `===`, and its wire form is a base64 string. These helpers back the kernel
// (`==`, `toBase64`, `decodeUtf8`) and the JSON codec (`fromBase64`).

// Content equality — the byte-for-byte compare the emitter lowers `==` to. The
// `===` fast path catches the identity case; otherwise length then each octet.
export function __bynkBytesEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

// Total encode: the standard base64 of the octet sequence. Every byte is
// 0..255, so the Latin-1 string handed to `btoa` never overflows.
export function __bynkBytesToBase64(bytes: Uint8Array): string {
  let bin = "";
  for (let i = 0; i < bytes.length; i++) {
    bin += String.fromCharCode(bytes[i]);
  }
  return btoa(bin);
}

// Partial decode: `Some(bytes)` for a valid standard-base64 string, `None`
// otherwise. The alphabet/padding are validated up front so a malformed string
// is a clean `None`, not a silently truncated buffer (some `atob`
// implementations are lenient). The empty string decodes to empty bytes — the
// round-trip of `Bytes.empty`.
export function __bynkBytesFromBase64(s: string): Option<Uint8Array> {
  if (s.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(s)) {
    return None;
  }
  let bin: string;
  try {
    bin = atob(s);
  } catch {
    return None;
  }
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) {
    out[i] = bin.charCodeAt(i);
  }
  return Some(out);
}

// Partial decode to text: `Some(string)` when the octets are valid UTF-8,
// `None` otherwise. `fatal: true` makes an invalid sequence throw rather than
// emit replacement characters, so the partiality is real and surfaced.
export function __bynkBytesDecodeUtf8(bytes: Uint8Array): Option<string> {
  try {
    return Some(new TextDecoder("utf-8", { fatal: true }).decode(bytes));
  } catch {
    return None;
  }
}

// #2016 (standard-library K1): the `Bytes` operations. Each is pure,
// synchronous and uses only typed arrays and `btoa`/`atob`, which Cloudflare,
// Node and browsers all provide. `slice` lowers inline (`Uint8Array.slice`,
// clamped like `String.slice`), so it has no helper here.

// A fresh buffer holding `a`'s octets then `b`'s. It never aliases either input.
export function __bynkBytesConcat(a: Uint8Array, b: Uint8Array): Uint8Array {
  const out = new Uint8Array(a.length + b.length);
  out.set(a, 0);
  out.set(b, a.length);
  return out;
}

// Unsigned lexicographic order: -1, 0 or 1. The first differing octet decides,
// and a proper prefix sorts first. Not constant-time: it returns at the first
// difference, so it must never compare secrets.
export function __bynkBytesCompare(a: Uint8Array, b: Uint8Array): number {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  }
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

const HEX_DIGITS = "0123456789abcdef";

// Total encode: two lowercase hex digits per octet, no prefix or separators.
export function __bynkBytesToHex(bytes: Uint8Array): string {
  let out = "";
  for (let i = 0; i < bytes.length; i++) {
    out += HEX_DIGITS[bytes[i] >> 4] + HEX_DIGITS[bytes[i] & 0x0f];
  }
  return out;
}

// Partial decode: either case, an even number of digits, nothing else (no
// `0x`, no whitespace, no separators). `""` decodes to empty bytes, so
// `fromHex(toHex(b))` round-trips every `b`.
export function __bynkBytesFromHex(s: string): Option<Uint8Array> {
  if (!/^(?:[0-9a-fA-F]{2})*$/.test(s)) {
    return None;
  }
  const out = new Uint8Array(s.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(s.slice(i * 2, i * 2 + 2), 16);
  }
  return Some(out);
}

// Total encode: RFC 4648 §5 base64url (`-` and `_`) with no padding, the JWT
// (RFC 7515) form.
export function __bynkBytesToBase64Url(bytes: Uint8Array): string {
  return __bynkBytesToBase64(bytes).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

// Partial decode: the URL-safe alphabet, with no padding or exactly the padding
// the length needs. A standard-alphabet character (`+`, `/`), wrong padding, an
// impossible length (`length % 4 == 1`) or non-zero spare bits in the last
// character is `None`. That last rule makes the decode canonical: `atob` drops
// the spare bits, so without it `"Zh"` and `"Zg"` would both decode to `"f"`,
// and a signed token segment could be re-spelled without changing its bytes.
export function __bynkBytesFromBase64Url(s: string): Option<Uint8Array> {
  const m = /^([A-Za-z0-9_-]*)(={0,2})$/.exec(s);
  if (m === null) {
    return None;
  }
  const body = m[1];
  const pad = m[2];
  if (body.length % 4 === 1) {
    return None;
  }
  const need = (4 - (body.length % 4)) % 4;
  if (pad.length !== 0 && pad.length !== need) {
    return None;
  }
  const decoded = __bynkBytesFromBase64(body.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat(need));
  if (decoded.tag === "Some" && __bynkBytesToBase64Url(decoded.value) !== body) {
    return None;
  }
  return decoded;
}

// #1652 (runtime-semantics track §3.1): structural `==` for every type the
// emitter cannot compare with a bare `===`.
//
// The emitter dispatches `==` by the operand's type (`lower_bin_op`, the same
// operand-typed shape as `Int`/`Float` division):
// - a statically primitive operand (a base type other than `Bytes`, or a
//   refined/opaque type over one) keeps `===`;
// - `Bytes`, including an opaque type over it, uses `__bynkBytesEqual`;
// - everything else uses `__bynkEq`.
//
// A type-directed `equals_T` per type was rejected: Bynk generic functions are
// not monomorphised (they emit as TS generics), so `==` on a type parameter has
// no concrete type to dispatch on. The in-memory representation describes
// itself instead, so this walker needs no type information:
//
// - primitives compare with `===`, keeping IEEE semantics: `NaN != NaN` and
//   `-0 == 0`, at any depth;
// - a `Uint8Array` (`Bytes`) compares by content;
// - an array (`List`) compares element-wise;
// - a `Map` (value-level `Map`) compares by size, then by key and value;
// - a plain object (a record, a sum value `{ tag, … }`, an `Option`/`Result`)
//   compares by its own keys and their values, so `tag` decides first;
// - an instance of any other class compares by identity. The checker rejects
//   `==` on the only such values a program holds (held connections), so this
//   is a fallback, not a semantic.
//
// The checker guarantees both operands have the same type, so shapes can only
// differ by variant or by value, never by kind.

export function __bynkEq(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) {
    return false;
  }
  if (a instanceof Uint8Array || b instanceof Uint8Array) {
    return a instanceof Uint8Array && b instanceof Uint8Array && __bynkBytesEqual(a, b);
  }
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!__bynkEq(a[i], b[i])) return false;
    }
    return true;
  }
  if (a instanceof Map || b instanceof Map) {
    if (!(a instanceof Map) || !(b instanceof Map) || a.size !== b.size) return false;
    for (const [k, v] of a) {
      if (!b.has(k) || !__bynkEq(v, b.get(k))) return false;
    }
    return true;
  }
  const pa = Object.getPrototypeOf(a);
  const pb = Object.getPrototypeOf(b);
  const plain = (p: unknown) => p === Object.prototype || p === null;
  if (!plain(pa) || !plain(pb)) return false;
  const ka = Object.keys(a);
  const kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) {
    if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
    if (!__bynkEq((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k])) {
      return false;
    }
  }
  return true;
}

// #1657 (runtime-semantics track §3.4): an `Int` is a JS safe integer,
// ±(2^53 − 1). These are the two in-language operations that would otherwise
// produce an `Int` outside that domain; each faults instead.
//
// They live here rather than inline in generated code so that `bynkc test
// --coverage`, which attributes only `.bynk` source, does not report the
// never-taken fault branch on every division or conversion line.

// `Int` division truncates toward zero; division by zero is a runtime fault
// rather than `Infinity`/`NaN` as an `Int`.
export function __bynkIntDiv(l: number, r: number): number {
  if (r === 0) throw new Error("Int division by zero");
  return Math.trunc(l / r);
}

// A Float→`Int` conversion (`round`/`floor`/`ceil`/`truncate`): the converted
// value must be a safe integer, which rules out a non-finite `Float` and one
// past ±2^53.
export function __bynkToInt(converted: number, op: string): number {
  if (!Number.isSafeInteger(converted)) {
    throw new Error(`Float.${op}: result is not a safe Int`);
  }
  return converted;
}

export interface ValidationError {
  readonly field: string;
  readonly message: string;
  readonly value: unknown;
}

// v0.22b: the JSON-decode error (ADR 0047) — BoundaryError's information
// (the discriminating kind and the tracked field path) flattened into a
// uniform, Bynk-inspectable record. `kind` is "Malformed" for a JSON.parse
// failure, else the BoundaryError kind ("StructuralMismatch",
// "RefinementViolation").
export interface JsonError {
  readonly kind: string;
  readonly path: string;
  readonly message: string;
}

// v0.80 (§14): an agent invariant violated at the commit boundary. A dedicated
// internal fault — distinct from BoundaryError (the cross-Worker call/refinement
// layer) — thrown inside the generated `commitState` *before* the proposed state
// is persisted, so the offending commit never lands. It rides the existing
// uncaught-fault channel: the caller observes a fault, not an outcome (ADR 0107).
export interface InvariantViolation {
  readonly kind: "InvariantViolation";
  readonly agent: string;
  readonly invariant: string;
}

export function invariantViolation(agent: string, invariant: string): Error {
  const e = new Error(`InvariantViolation: ${agent}.${invariant}`);
  (e as { invariantViolation?: InvariantViolation }).invariantViolation = {
    kind: "InvariantViolation",
    agent,
    invariant,
  };
  return e;
}

export interface DurableObjectStorage {
  get<T>(key: string): Promise<T | undefined>;
  put(key: string, value: unknown): Promise<void>;
  delete(key: string): Promise<boolean>;
  list<T>(options?: { prefix?: string }): Promise<Map<string, T>>;
}

export interface DurableObjectState {
  readonly storage: DurableObjectStorage;
  readonly id: { readonly name: string };
}

/**
 * Copy a stored value the way a Durable Object's storage round-trip does, for
 * every value that is **data**. #1660 (runtime-semantics track §3.5).
 *
 * - **Copied deeply:** plain objects, arrays, `Map`, `Uint8Array`, `Date`.
 * - **Passed through by reference:** an instance of any other class.
 *
 * The only such instances agent state holds are live handles. A held
 * `Connection` on the bundle target is a `TestConnection` stored directly in
 * state. On workers, a held connection persists its `connId` instead, and
 * `resolveConnection` re-presents the **same** live socket on load, so sharing
 * the handle here is the faithful analogue. `structuredClone` would instead
 * strip the handle's methods, and `send` would vanish.
 */
function cloneStored<T>(value: T): T {
  if (value === null || typeof value !== "object") return value;
  // `new Uint8Array(v)` copies; `slice()` on a Node `Buffer` (a Uint8Array) is a view.
  if (value instanceof Uint8Array) return new Uint8Array(value) as T;
  if (value instanceof Date) return new Date(value.getTime()) as T;
  if (value instanceof Map) {
    return new Map([...value].map(([k, v]) => [cloneStored(k), cloneStored(v)])) as T;
  }
  if (Array.isArray(value)) return value.map(cloneStored) as T;
  const proto = Object.getPrototypeOf(value);
  if (proto !== Object.prototype && proto !== null) return value;
  // `Object.fromEntries` *defines* each key, where `out[k] = v` would *set* it.
  // For an own `__proto__` key (which `JSON.parse` creates, so a decoded record
  // stored as a `Map[String, _]` can carry one), a set would reassign the copy's
  // prototype, or silently drop a primitive, instead of copying the entry.
  return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, cloneStored(v)])) as T;
}

/**
 * The bundle-target (and `bynkc test`) stand-in for a Durable Object's storage.
 *
 * #1660 (runtime-semantics track §3.5): every value is copied (`cloneStored`) on
 * the way in **and** on the way out, as workerd's storage copies it. A value read
 * back is never the object that was written. Two things depend on this.
 *
 * - **Fidelity.** Before #1660 this class handed back the stored reference. That
 *   let `bynkc test` pass programs that cannot work under workerd. A loaded enum
 *   compared `===` against its singleton constant (so reference `==`, #1652, was
 *   masked), and a handler's write through a shallow copy of loaded state was
 *   visible to the next load.
 * - **Atomicity (ADR 0109).** A handler begins from
 *   `{ ...(await this.loadState()) }`, which is a shallow copy. With a shared
 *   reference, a store write such as `__state.items[k] = v` mutated the record
 *   still held here, so a commit later *refused* by an invariant had already
 *   happened. Cloning on `get` gives each handler its own state, so a refused
 *   commit leaves storage untouched. The regression is pinned by
 *   `bynkc/tests/store_behaviour.rs`'s
 *   `refused_commit_does_not_leak_an_in_place_store_write`.
 */
export class InMemoryStorage implements DurableObjectStorage {
  private data = new Map<string, unknown>();

  async get<T>(key: string): Promise<T | undefined> {
    const value = this.data.get(key);
    return (value === undefined ? undefined : cloneStored(value)) as T | undefined;
  }

  async put(key: string, value: unknown): Promise<void> {
    this.data.set(key, cloneStored(value));
  }

  async delete(key: string): Promise<boolean> {
    return this.data.delete(key);
  }

  async list<T>(options?: { prefix?: string }): Promise<Map<string, T>> {
    const prefix = options?.prefix ?? "";
    const out = new Map<string, T>();
    for (const [k, v] of this.data) {
      if (k.startsWith(prefix)) out.set(k, cloneStored(v) as T);
    }
    return out;
  }
}

export function makeTestState(name: string): DurableObjectState {
  return {
    storage: new InMemoryStorage(),
    id: { name },
  };
}

export interface KVNamespace {
  get(key: string): Promise<string | null>;
  put(key: string, value: string, options?: { expirationTtl?: number }): Promise<void>;
  delete(key: string): Promise<void>;
  // v0.23: the page shape WorkersKv's drain consumes (0050).
  list(options?: { prefix?: string; cursor?: string }): Promise<{
    keys: { name: string }[];
    list_complete: boolean;
    cursor?: string;
  }>;
}

/**
 * #1959: an in-memory KV namespace for multi-Worker integration tests. The
 * harness makes a fresh one per participant per test case and binds it as
 * that participant's `env.KV`, as `bynk deploy` provisions one namespace per
 * Worker. Keys list in order, on one page; `expirationTtl` is accepted and
 * ignored, since a test case does not outlive it.
 */
export function makeIntegrationKv(): KVNamespace {
  const values = new Map<string, string>();
  return {
    async get(key: string): Promise<string | null> {
      return values.get(key) ?? null;
    },
    async put(key: string, value: string): Promise<void> {
      values.set(key, value);
    },
    async delete(key: string): Promise<void> {
      values.delete(key);
    },
    async list(options?: { prefix?: string; cursor?: string }) {
      const prefix = options?.prefix ?? "";
      const names = [...values.keys()].filter((k) => k.startsWith(prefix)).sort();
      return { keys: names.map((name) => ({ name })), list_complete: true };
    },
  };
}

/**
 * P5 (#2323): the part of Cloudflare's `R2Bucket` that `WorkersR2` uses,
 * declared here so the binding and the in-memory double share one shape.
 * `put` resolves `null` when its `onlyIf` precondition failed;
 * `etagDoesNotMatch: "*"` is the create-only precondition.
 */
export interface R2ObjectMeta {
  readonly key: string;
  readonly size: number;
  readonly etag: string;
  readonly uploaded: Date;
  readonly httpMetadata?: { contentType?: string };
  readonly customMetadata?: Record<string, string>;
}

export interface R2ObjectBody extends R2ObjectMeta {
  arrayBuffer(): Promise<ArrayBuffer>;
}

export interface R2PutOptions {
  httpMetadata?: { contentType?: string };
  customMetadata?: Record<string, string>;
  onlyIf?: { etagMatches?: string; etagDoesNotMatch?: string };
}

export interface R2Bucket {
  get(key: string): Promise<R2ObjectBody | null>;
  head(key: string): Promise<R2ObjectMeta | null>;
  put(key: string, value: Uint8Array, options?: R2PutOptions): Promise<R2ObjectMeta | null>;
  delete(key: string): Promise<void>;
  list(options?: {
    prefix?: string;
    cursor?: string;
    limit?: number;
    include?: ("httpMetadata" | "customMetadata")[];
  }): Promise<{ objects: R2ObjectMeta[]; truncated: boolean; cursor?: string }>;
}

/**
 * An in-memory R2 bucket for multi-Worker integration tests, bound as that
 * participant's `env.R2_<NAME>` and fresh per test case, as `makeIntegrationKv`
 * is. It honours the preconditions `WorkersR2` sends and pages `list` in key
 * order at R2's own page size (`limit`, default 1000), the cursor being the
 * last key returned.
 */
export function makeIntegrationR2(): R2Bucket {
  type Stored = { meta: R2ObjectMeta; body: Uint8Array };
  const objects = new Map<string, Stored>();
  let version = 0;
  return {
    async get(key: string): Promise<R2ObjectBody | null> {
      const s = objects.get(key);
      if (!s) return null;
      const body = s.body;
      return {
        ...s.meta,
        async arrayBuffer(): Promise<ArrayBuffer> {
          return body.slice().buffer as ArrayBuffer;
        },
      };
    },
    async head(key: string): Promise<R2ObjectMeta | null> {
      return objects.get(key)?.meta ?? null;
    },
    async put(key: string, value: Uint8Array, options?: R2PutOptions): Promise<R2ObjectMeta | null> {
      const current = objects.get(key);
      const cond = options?.onlyIf;
      if (cond?.etagMatches !== undefined && current?.meta.etag !== cond.etagMatches) return null;
      if (cond?.etagDoesNotMatch !== undefined) {
        const clash = cond.etagDoesNotMatch === "*" ? current !== undefined : current?.meta.etag === cond.etagDoesNotMatch;
        if (clash) return null;
      }
      version += 1;
      const body = value.slice();
      const contentType = options?.httpMetadata?.contentType;
      const meta: R2ObjectMeta = {
        key,
        size: body.length,
        etag: `etag-${version}`,
        uploaded: new Date(),
        httpMetadata: contentType === undefined ? {} : { contentType },
        customMetadata: { ...(options?.customMetadata ?? {}) },
      };
      objects.set(key, { meta, body });
      return meta;
    },
    async delete(key: string): Promise<void> {
      objects.delete(key);
    },
    async list(options) {
      const prefix = options?.prefix ?? "";
      const limit = options?.limit ?? 1000;
      const after = options?.cursor;
      const keys = [...objects.keys()]
        .filter((k) => k.startsWith(prefix) && (after === undefined || k > after))
        .sort();
      const page = keys.slice(0, limit);
      const truncated = keys.length > page.length;
      return {
        objects: page.map((k) => objects.get(k)!.meta),
        truncated,
        cursor: truncated ? page[page.length - 1] : undefined,
      };
    },
  };
}

// v0.8: cross-Worker boundary protocol — JSON wire format and error types.

export type JsonValue =
  | null
  | boolean
  | number
  | string
  | JsonValue[]
  | { [k: string]: JsonValue };

export type BoundaryError =
  | { readonly kind: "MalformedJson"; readonly details: string }
  | {
      readonly kind: "StructuralMismatch";
      readonly path: string;
      readonly expected: string;
      readonly actual: string;
    }
  | {
      readonly kind: "RefinementViolation";
      readonly path: string;
      readonly violation: ValidationError;
    }
  | { readonly kind: "Transport"; readonly status: number; readonly details: string };

// v0.177 (#643): the deployed callee's compiled contract is not the one this
// caller was compiled against — a deploy skew, not a bad payload. The callee
// reports it as a 409 *before* reading the body, since once the contracts
// disagree the body's interpretation is exactly what is in doubt.
//
// Deliberately **not** a `BoundaryError` variant. `BoundaryError` is the
// *codec's* error domain — what deserialising a payload can conclude — and a
// codec can never produce this: it is decided from a header before any codec
// runs. Widening `BoundaryError` would oblige every consumer of a codec result
// (`Json.decode`'s error mapping among them) to narrow a case it can never
// observe. The call surface is wider than the codec surface, so it gets its own
// type.
export interface ContractMismatch {
  readonly kind: "ContractMismatch";
  readonly service: string;
  readonly expected: string;
  readonly actual: string | null;
}

/// #2193: the callee's handler faulted. It answered the bare `500` every fault
/// answers, marked with [`FAULT_HEADER`] naming its context, so the caller
/// reports which Worker's log holds the cause instead of a `Transport`
/// failure that reads like an unreachable callee. Like `ContractMismatch`, a
/// call-surface error, never a codec result. The error itself stays in the
/// callee's log: the response carries only the callee's name.
export interface CalleeFaulted {
  readonly kind: "CalleeFaulted";
  readonly context: string;
  readonly service: string;
  readonly status: number;
}

/// #2193: the header a callee's fault response names its context in.
export const FAULT_HEADER = "X-Bynk-Fault";

/// Everything a cross-context call can fail with: the codec's domain, plus the
/// skew check that precedes it and a callee's fault.
export type CallError = BoundaryError | ContractMismatch | CalleeFaulted;

/// #2193: the `500` a Worker entry answers when a handler faults. A fault in an
/// `on call` service (`route` is `call <service>`) is marked with
/// [`FAULT_HEADER`], so the calling Worker's `callService` can name it; any
/// other route's `500` is unmarked, as before.
export function faultResponse(context: string, route: string): Response {
  const headers: Record<string, string> = route.startsWith("call ") ? { [FAULT_HEADER]: context } : {};
  return new Response("Internal Server Error", { status: 500, headers });
}

export function boundaryError(error: CallError): Error {
  const e = new Error(`BoundaryError: ${error.kind}`) as Error & {
    boundaryError?: CallError;
  };
  // #1825 review: non-enumerable, so a logged error (`console.error(..., e)`
  // in a Worker's fault catch) doesn't print the payload, which can carry a
  // value: a callee's response body, a refinement's offending value. Reading
  // `e.boundaryError` is unchanged.
  globalThis.Object.defineProperty(e, "boundaryError", {
    value: error,
    enumerable: false,
    writable: true,
    configurable: true,
  });
  return e;
}

// v0.96 (ADR 0124): an agent's persisted state failed validation on rehydration —
// a refined field, key, or entry no longer satisfies the current type definition
// (schema corruption, or a refinement that tightened across a deploy, orphaning
// previously-valid data). The load-time twin of InvariantViolation: a dedicated
// internal fault, NOT a caller-facing BoundaryError, because the supplier is
// trusted past-self, not the untrusted caller (Q6). It reuses the boundary
// validator's *detection* (the BoundaryError detail) but disposes of it as a
// fault. Logged with the agent type and field path only — never the key or the
// offending value (ADR 0107 logging discipline).
export interface RehydrationViolation {
  readonly kind: "RehydrationViolation";
  readonly agent: string;
  readonly path: string;
  readonly detail: BoundaryError | SchemaVersionMismatch | MigrationFailed;
}

// State-migrations S2 (#2224 Decision D): a `migrate from N` step threw while
// running (for example, an `Int` division by zero). Only the step's version is
// recorded — never the thrown value, which can carry stored data.
export interface MigrationFailed {
  readonly kind: "MigrationFailed";
  readonly from: number;
}

// State-migrations S1 (#2211): a stored record's `__v` schema-version marker
// does not let this build read it. `NewerSchema`: a newer build wrote it (the
// deploy was rolled back). `NoMigrationPath`: it is malformed, or older than
// the oldest version this build reads forward without a migration step.
// `stored` is null when the marker is not a positive integer. Version numbers
// are not user data, so they are logged.
export interface SchemaVersionMismatch {
  readonly kind: "NewerSchema" | "NoMigrationPath";
  readonly stored: number | null;
  readonly current: number;
  readonly oldestReadable: number;
}

// State-migrations S1 (#2211, track §3.2): check a raw stored record's `__v`
// marker before anything is decoded or merged (Decision D). An absent marker
// is version 1, the lock's baseline. A record at a version from
// `oldestReadable` to `current` reads by zero-merge (ADR 0124 D4); anything
// newer is `NewerSchema`, anything else `NoMigrationPath` — both thrown as a
// `RehydrationViolation`, so a faulting record is never decoded or written
// back.
//
// State-migrations S2 (#2224 Decision C): `steps` lists each `migrate from N`
// step's covered range as `[lo, N]`; a version inside one is readable too.
export function checkStoredSchemaVersion(
  agent: string,
  stored: object,
  current: number,
  oldestReadable: number,
  steps: readonly (readonly [number, number])[] = [],
): void {
  const raw = (stored as { readonly __v?: unknown }).__v;
  const v = raw === undefined ? 1 : raw;
  const valid = typeof v === "number" && globalThis.Number.isInteger(v) && v >= 1;
  if (valid && v <= current && v >= oldestReadable) return;
  if (valid && steps.some(([lo, n]) => v >= lo && v <= n)) return;
  throw rehydrationViolation(agent, {
    kind: valid && v > current ? "NewerSchema" : "NoMigrationPath",
    stored: valid ? v : null,
    current,
    oldestReadable,
  });
}

// State-migrations S1 (#2211, track §3.4): warn, once per isolate per
// (agent, key), about a stored key the current definition does not declare — a
// field renamed or removed before the schema lock recorded it. The key is kept
// and written back, never deleted. `zero` is the agent's fresh record, so every
// key the toolchain itself keeps in state counts as declared. Logs the key's
// name only, never its value (ADR 0107).
const reportedUnknownStoredKeys = new globalThis.Set<string>();
export function reportUnknownStoredKeys(agent: string, stored: object, zero: object): void {
  for (const key of globalThis.Object.keys(stored)) {
    if (key === "__v" || globalThis.Object.hasOwn(zero, key)) continue;
    const id = `${agent}\u0000${key}`;
    if (reportedUnknownStoredKeys.has(id)) continue;
    reportedUnknownStoredKeys.add(id);
    globalThis.console.warn(
      `bynk: agent ${agent} has stored field "${key}" the current definition does not declare; it is kept, not read`,
    );
  }
}

// State-migrations S2 (#2224 Decision D): the fault a step that throws
// becomes. The thrown value is discarded, not logged: it can carry stored data.
export function migrationFailed(agent: string, from: number): Error {
  return rehydrationViolation(agent, { kind: "MigrationFailed", from });
}

export function rehydrationViolation(
  agent: string,
  detail: BoundaryError | SchemaVersionMismatch | MigrationFailed,
): Error {
  const path = "path" in detail ? detail.path : "<root>";
  // #1827: logged here, where every load-time gate builds it, as the
  // `InvariantViolation` line is logged before its throw: the agent, the field
  // path and the kind of failure. Never `detail` itself, which can carry the
  // offending value (a `RefinementViolation`'s `violation.value`). A schema
  // version mismatch carries only version numbers, which are logged.
  globalThis.console.error(
    `RehydrationViolation ${agent}`,
    "current" in detail
      ? { agent, path, kind: detail.kind, stored: detail.stored, current: detail.current }
      : "from" in detail
        ? { agent, path, kind: detail.kind, from: detail.from }
        : { agent, path, kind: detail.kind },
  );
  const e = new Error(`RehydrationViolation: ${agent} ${detail.kind} at ${path}`);
  // #1825 review: non-enumerable, as `boundaryError`'s, so a logged error
  // doesn't print `detail` (it can carry the offending value).
  globalThis.Object.defineProperty(e, "rehydrationViolation", {
    value: {
      kind: "RehydrationViolation",
      agent,
      path,
      detail,
    } satisfies RehydrationViolation,
    enumerable: false,
    writable: true,
    configurable: true,
  });
  return e;
}

export interface ServiceBinding {
  fetch(request: Request): Promise<Response>;
}

// I2 (#1971, ADR `per-edge-call-signature`, amending ADR 0092): every
// internal request (`/_bynk/call/`, `/_bynk/event/`) is signed with
// HMAC-SHA256 under a key one caller shares with one callee, and the callee
// refuses a request whose signature does not verify before it reads anything
// else. The path prefixes are reachable from the public internet on any route
// the Worker serves, so the prefix alone proves nothing about the sender, and
// one key per edge means a key's holder can claim only its own name. Bynk's
// emitter holds the same values in `bynk_check::wire_format`, and
// `bynkc/tests/wire_reference.rs` fails if the two disagree.
export const CALLER_HEADER = "X-Bynk-Caller";
export const TIMESTAMP_HEADER = "X-Bynk-Timestamp";
export const SIGNATURE_HEADER = "X-Bynk-Signature";
export const SIGNATURE_WINDOW_SECONDS = 300;
export const MAX_BODY_BYTES = 1048576;
export const SIGNING_SCHEME = "BYNK-CALL-1";
export const EDGE_FROM_PREFIX = "BYNK_CALL_FROM_";
export const EDGE_TO_PREFIX = "BYNK_CALL_TO_";

// A context name an edge key can be derived from: dot-separated segments of
// lowercase letters and digits, starting with a letter, with single
// underscores between runs. On these names `edgeSuffix` is injective, so one
// caller's key never verifies another caller's name.
const EDGE_NAME = /^[a-z][a-z0-9]*(?:_[a-z0-9]+)*(?:\.[a-z][a-z0-9]*(?:_[a-z0-9]+)*)*$/;

// `shop.orders` → `SHOP__ORDERS`, or `undefined` outside the domain above.
export function edgeSuffix(context: string): string | undefined {
  return EDGE_NAME.test(context) ? context.toUpperCase().split(".").join("__") : undefined;
}

// The edge key under `prefix` + the context's suffix in a Worker's `env`, or
// `undefined` when the name is outside the domain, or the key unset or not a
// non-empty string. `env` is `unknown` because the keys are secrets, not
// declared bindings, so no generated `Env` interface names them (the actor
// auth secrets read theirs the same way).
export function edgeKeyOf(env: unknown, prefix: string, context: string): string | undefined {
  const suffix = edgeSuffix(context);
  if (suffix === undefined || typeof env !== "object" || env === null) return undefined;
  const value = (env as Record<string, unknown>)[prefix + suffix];
  return typeof value === "string" && value !== "" ? value : undefined;
}

// I3 (#1971): a foreign caller's secret, by its declared name, from `env`.
function foreignKeyOf(env: unknown, name: string): string | undefined {
  if (typeof env !== "object" || env === null) return undefined;
  const value = (env as Record<string, unknown>)[name];
  return typeof value === "string" && value !== "" ? value : undefined;
}

// The fields a signature covers, one per line (`signing_input` in
// `bynk_check::wire_format`). Every header the callee acts on is here; an
// absent contract is signed as empty and an absent wire version as `1`.
export interface SignedFields {
  caller: string;
  callee: string;
  method: string;
  path: string;
  contract: string;
  wire: string;
  timestamp: string;
  bodyDigest: string;
}

export function signingInput(f: SignedFields): string {
  return [SIGNING_SCHEME, f.caller, f.callee, f.method, f.path, f.contract, f.wire, f.timestamp, f.bodyDigest].join("\n");
}

function hex(bytes: ArrayBuffer): string {
  return Array.from(new Uint8Array(bytes), (b) => b.toString(16).padStart(2, "0")).join("");
}

async function sha256Hex(bytes: Uint8Array<ArrayBuffer>): Promise<string> {
  return hex(await crypto.subtle.digest("SHA-256", bytes));
}

function hmacKey(secret: string, usage: "sign" | "verify"): Promise<CryptoKey> {
  return crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, [usage]);
}

// The signature a caller holding `key` sends over `fields`.
export async function signature(key: string, fields: SignedFields): Promise<string> {
  return hex(await crypto.subtle.sign("HMAC", await hmacKey(key, "sign"), new TextEncoder().encode(signingInput(fields))));
}

// The sending side: the headers that prove `caller` sent `body` to `callee`.
// Throws, naming the unset key, when the Worker holds none for the edge:
// sending without it would only come back as an opaque 401.
export async function signedHeaders(
  env: unknown,
  caller: string,
  callee: string,
  path: string,
  contract: string,
  // The wire version as sent; `"1"` for a request that sends no header.
  wire: string,
  body: string,
  what: string,
): Promise<Record<string, string>> {
  const key = edgeKeyOf(env, EDGE_TO_PREFIX, callee);
  if (key === undefined) {
    throw new Error(
      `${EDGE_TO_PREFIX}${edgeSuffix(callee) ?? callee} is not set, so ${what} cannot be sent: \`bynk deploy\` sets one key per calling edge, and \`bynk dev\` passes a local one.`,
    );
  }
  const timestamp = String(Math.floor(Date.now() / 1000));
  const bodyDigest = await sha256Hex(new TextEncoder().encode(body));
  const sig = await signature(key, { caller, callee, method: "POST", path, contract, wire, timestamp, bodyDigest });
  return { [CALLER_HEADER]: caller, [TIMESTAMP_HEADER]: timestamp, [SIGNATURE_HEADER]: sig };
}

// The body's bytes, read under `cap` (`MAX_BODY_BYTES` for the internal
// dispatch; a route's effective `maxBody` for `from http`), or `undefined` once
// it is past the cap: a declared length is refused before reading, and a
// streamed body is cancelled as soon as it crosses the cap, so an
// unauthenticated sender cannot make the callee buffer an unbounded body. The
// count is of the bytes actually read, so a chunked body, or one whose
// `Content-Length` understates it, is cut off all the same.
export async function readCapped(
  request: Request,
  cap: number = MAX_BODY_BYTES,
): Promise<Uint8Array<ArrayBuffer> | undefined> {
  const declared = request.headers.get("content-length");
  if (declared !== null && Number(declared) > cap) return undefined;
  if (request.body === null) return new Uint8Array(0);
  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let size = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    size += value.byteLength;
    if (size > cap) {
      await reader.cancel();
      return undefined;
    }
    chunks.push(value);
  }
  const bytes = new Uint8Array(size);
  let at = 0;
  for (const c of chunks) {
    bytes.set(c, at);
    at += c.byteLength;
  }
  return bytes;
}

const SIGNATURE_SHAPE = /^[0-9a-f]{64}$/;
const TIMESTAMP_SHAPE = /^[0-9]{1,15}$/;

// The receiving side, the first thing every internal dispatch does: the body
// as text when `request` is signed for `callee` by a caller this Worker holds
// a key for, within the window; otherwise the refusal to return, a bare 413
// or 401. Fails closed: a caller with no key here (an undeclared or forged
// one, or any caller when no key is set) is refused. `crypto.subtle.verify`
// compares in constant time.
//
// I3 (#1971): `foreign` maps each foreign caller the callee admits (a
// `Foreign` actor's name, which it sends as its caller) to the secret it signs
// under. Such a name is never a context's (an actor name starts with a capital
// letter, which `edgeSuffix` refuses), so a foreign caller is checked under
// its own secret and a Bynk caller under its edge key, and neither can pass
// for the other. Looked up with `Object.hasOwn`, never plain indexing, so a
// caller named after an `Object.prototype` member finds nothing.
export async function verifyCall(
  request: Request,
  env: unknown,
  callee: string,
  foreign: Record<string, string> = {},
): Promise<string | Response> {
  const bytes = await readCapped(request);
  if (bytes === undefined) return new Response("Payload Too Large", { status: 413 });
  const refused = new Response("Unauthorized", { status: 401 });
  const caller = request.headers.get(CALLER_HEADER) ?? "";
  const key = Object.hasOwn(foreign, caller) ? foreignKeyOf(env, foreign[caller]) : edgeKeyOf(env, EDGE_FROM_PREFIX, caller);
  if (key === undefined) return refused;
  const timestamp = request.headers.get(TIMESTAMP_HEADER) ?? "";
  if (!TIMESTAMP_SHAPE.test(timestamp)) return refused;
  if (Math.abs(Date.now() / 1000 - Number(timestamp)) > SIGNATURE_WINDOW_SECONDS) return refused;
  const given = request.headers.get(SIGNATURE_HEADER) ?? "";
  if (!SIGNATURE_SHAPE.test(given)) return refused;
  const sig = new Uint8Array(32);
  for (let i = 0; i < 32; i++) sig[i] = parseInt(given.slice(2 * i, 2 * i + 2), 16);
  const fields: SignedFields = {
    caller,
    callee,
    method: request.method,
    path: new URL(request.url).pathname,
    contract: request.headers.get("X-Bynk-Contract") ?? "",
    wire: request.headers.get(WIRE_VERSION_HEADER) ?? "1",
    timestamp,
    bodyDigest: await sha256Hex(bytes),
  };
  const ok = await crypto.subtle.verify(
    "HMAC",
    await hmacKey(key, "verify"),
    sig,
    new TextEncoder().encode(signingInput(fields)),
  );
  return ok ? new TextDecoder().decode(bytes) : refused;
}

// #1969: the published cross-context wire format's version
// (`reference/wire-format.md`). A caller states the version it speaks; a callee
// accepts a range of them and treats an absent header as version 1. Bynk's
// emitter holds the same values in `bynk_check::wire_format`, and
// `bynkc/tests/wire_reference.rs` fails if the two disagree.
export const WIRE_VERSION_HEADER = "X-Bynk-Wire";
export const WIRE_VERSION = "1";

export async function callService<R>(
  binding: ServiceBinding,
  servicePath: string,
  argsJson: JsonValue,
  // #988: generic over the whole return type `R`, not a `Result`'s two
  // halves — `R = Result<T, E>` recovers the old behaviour exactly, but a
  // plain (non-`Result`) `R` now has something to bind `deserialiseResult`'s
  // inference to, instead of degrading to `unknown`. The `path` parameter is
  // optional here because every generated `deserialise_*` declares it with a
  // default, which callers of this function are not required to match.
  deserialiseResult: (json: JsonValue, path?: string) => Result<R, BoundaryError>,
  // v0.54: the calling context's qualified name, stamped beside the args so the
  // callee's `by c: Caller` handler can present a live `CallerId` (Q7). A
  // compile-time constant; the args body itself is unchanged. The `Internal`
  // channel trusts the binding, so this is identity, not authentication.
  callerContext: string = "",
  // v0.177 (#643): this caller's compiled hash of the callee's contract. A
  // compile-time constant, stamped beside the caller identity as metadata — the
  // args body is untouched. The callee compares it against its own constant and
  // fails closed on mismatch (409), which is what makes a `deploy --context`
  // skew a loud, nameable failure instead of a silent misinterpretation.
  contractHash: string = "",
  // I2 (#1971): the calling Worker's `env`, which holds the key for the edge
  // to `calleeContext` ([`EDGE_TO_PREFIX`]), and the callee's qualified name,
  // which the signature binds the request to.
  env: unknown = undefined,
  calleeContext: string = "",
): Promise<R> {
  const body = JSON.stringify(argsJson);
  const path = `/_bynk/call/${servicePath}`;
  const signed = await signedHeaders(env, callerContext, calleeContext, path, contractHash, WIRE_VERSION, body, `the call to ${servicePath}`);
  const request = new Request(`http://internal/_bynk/call/${servicePath}`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "X-Bynk-Caller": callerContext,
      "X-Bynk-Contract": contractHash,
      [WIRE_VERSION_HEADER]: WIRE_VERSION,
      ...signed,
    },
    body,
  });
  const response = await binding.fetch(request);
  if (!response.ok) {
    // Read the body **once**: the stream is consumed on first read, so a second
    // read throws `TypeError: Body is unusable` — which would replace the very
    // diagnosis this increment exists to give with an opaque failure from inside
    // the runtime.
    const raw = await response.text();
    // v0.177 (#643): a 409 from the internal boundary is the callee refusing a
    // skewed contract. Surface it as the named `ContractMismatch` rather than a
    // generic transport failure — the whole point of failing closed is that the
    // operator learns *what* is wrong, and "409 with an opaque body" would bury
    // it. Anything else — including a 409 that is not ours, or one whose body
    // does not parse — stays a `Transport`.
    if (response.status === 409) {
      let detail: ContractMismatch | null = null;
      try {
        detail = JSON.parse(raw) as ContractMismatch;
      } catch {
        // Not a Bynk 409; fall through to `Transport`.
      }
      if (detail && detail.kind === "ContractMismatch") {
        // #1826: logged on the caller's side too, with both hashes, before the
        // fault: the caller's catch reports only `BoundaryError: ContractMismatch`.
        globalThis.console.error(`ContractMismatch ${callerContext} -> ${servicePath}`, detail);
        throw boundaryError(detail);
      }
    }
    // #2193: a marked 500 is the callee's own fault. Logged here too, naming
    // the callee, so the caller's tail says which Worker's log to read. The
    // header is bounded in the log, as #1826 bounds the contract hash.
    const faulted = response.status === 500 ? response.headers.get(FAULT_HEADER) : null;
    if (faulted !== null) {
      const detail: CalleeFaulted = {
        kind: "CalleeFaulted",
        context: faulted.slice(0, 128),
        service: servicePath,
        status: response.status,
      };
      globalThis.console.error(`CalleeFaulted ${callerContext} -> ${detail.context} call ${servicePath}`);
      throw boundaryError(detail);
    }
    throw boundaryError({
      kind: "Transport",
      status: response.status,
      details: raw,
    });
  }
  let responseJson: JsonValue;
  try {
    responseJson = (await response.json()) as JsonValue;
  } catch (e) {
    throw boundaryError({ kind: "MalformedJson", details: String(e) });
  }
  const result = deserialiseResult(responseJson);
  if (result.tag === "Err") {
    throw boundaryError(result.error);
  }
  return result.value;
}

// Events track, slice 0: the fan-out DO's own delivery to one subscriber,
// over that subscriber's Service Binding. Subscriber failure isolation (ADR
// 0284) is the caller's responsibility — the fan-out DO catches per-subscriber
// so one subscriber's rejection does not stop delivery to its siblings; this
// helper itself just throws on a non-`ok` response.
//
// Slice 2 (spine #936): the POST body is `{ payload, envelope }`, not the
// bare payload — the envelope is always sent; whether the receiving
// subscriber's handler actually declared the optional `env: EventEnvelope`
// parameter is decided entirely on the receiving side (the `/_bynk/event/`
// route in the emitted `index.ts`), which forwards it to the handler only
// when that handler's own generated wrapper expects it.
export async function deliverEvent(
  binding: ServiceBinding,
  servicePath: string,
  payload: unknown,
  envelope: unknown,
  // I2 (#1971): the fan-out Durable Object's `env`, which holds the key for
  // the edge from the publishing context to the subscriber, and the two
  // contexts' qualified names. The subscriber verifies before it reads.
  env: unknown = undefined,
  publisher: string = "",
  subscriber: string = "",
): Promise<void> {
  const body = JSON.stringify({ payload, envelope });
  const path = `/_bynk/event/${servicePath}`;
  const signed = await signedHeaders(env, publisher, subscriber, path, "", "1", body, `the event delivery to ${servicePath}`);
  const request = new Request(`http://internal/_bynk/event/${servicePath}`, {
    method: "POST",
    headers: { "content-type": "application/json", ...signed },
    body,
  });
  const response = await binding.fetch(request);
  if (!response.ok) {
    throw new Error(`event delivery to ${servicePath} failed: ${response.status}`);
  }
}

// #973: `EventEnvelope` (`{ eventId, publisherId, emittedAt, schemaVersion }`)
// is declared in `adapter bynk`, not by a consumed context, so it never goes
// through the ordinary `emit_record_codec` machinery a context's own boundary
// types get (that machinery is rooted at a *consumed context's* exports;
// widening it to cover every adapter-declared type would touch every context
// that imports any `bynk` type, for one envelope). This hand-written validator
// is its sole codec, checked at the receiving `/_bynk/event/` route
// (`workers_entry.rs`) exactly once per delivery, unconditionally — the
// envelope is always on the wire regardless of whether a given subscriber's
// handler declared the optional `env: EventEnvelope` parameter. Field rules
// mirror the generated `Int`/`Instant` codec rule (`serialisation.rs`'s
// `TypeRef::Base` arm): both wire as `number`, integer-checked.
export function deserialiseEventEnvelope(
  json: JsonValue,
  path: string = "$",
): Result<
  { eventId: string; publisherId: string; emittedAt: number; schemaVersion: number },
  BoundaryError
> {
  if (typeof json !== "object" || json === null || Array.isArray(json)) {
    return Err({ kind: "StructuralMismatch", path, expected: "object", actual: typeof json });
  }
  const obj = json as { [k: string]: JsonValue };
  const eventId = obj["eventId"];
  if (typeof eventId !== "string") {
    return Err({
      kind: "StructuralMismatch",
      path: `${path}.eventId`,
      expected: "string",
      actual: typeof eventId,
    });
  }
  const publisherId = obj["publisherId"];
  if (typeof publisherId !== "string") {
    return Err({
      kind: "StructuralMismatch",
      path: `${path}.publisherId`,
      expected: "string",
      actual: typeof publisherId,
    });
  }
  const emittedAt = obj["emittedAt"];
  if (typeof emittedAt !== "number" || !Number.isInteger(emittedAt)) {
    return Err({
      kind: "StructuralMismatch",
      path: `${path}.emittedAt`,
      expected: "integer",
      actual: typeof emittedAt,
    });
  }
  const schemaVersion = obj["schemaVersion"];
  if (typeof schemaVersion !== "number" || !Number.isInteger(schemaVersion)) {
    return Err({
      kind: "StructuralMismatch",
      path: `${path}.schemaVersion`,
      expected: "integer",
      actual: typeof schemaVersion,
    });
  }
  return Ok({ eventId, publisherId, emittedAt, schemaVersion });
}

// v0.9: HttpResult — the built-in HTTP-result sum.

export type HttpResult<T> =
  // 2xx success — carries the serialised value.
  | { readonly tag: "Ok"; readonly value: T }
  // 2xx streamed body — SSE-framed (real-time track slice 1).
  | { readonly tag: "Streaming"; readonly stream: AsyncIterable<string> }
  // 2xx raw body — author-owned bytes with an explicit content-type (v0.111).
  | { readonly tag: "Raw"; readonly body: Uint8Array; readonly contentType: string }
  // 2xx raw body with a handler-supplied entity tag, sent as its `ETag` (caching raw responses).
  | {
      readonly tag: "RawTagged";
      readonly body: Uint8Array;
      readonly contentType: string;
      readonly etag: string;
    }
  | { readonly tag: "Created"; readonly value: T }
  | { readonly tag: "Accepted"; readonly value: T }
  | { readonly tag: "NoContent" }
  // 3xx redirection — carries the target URL, emitted as a Location header.
  | { readonly tag: "MovedPermanently"; readonly location: string }
  | { readonly tag: "Found"; readonly location: string }
  | { readonly tag: "SeeOther"; readonly location: string }
  | { readonly tag: "TemporaryRedirect"; readonly location: string }
  | { readonly tag: "PermanentRedirect"; readonly location: string }
  // 4xx client error.
  | { readonly tag: "BadRequest"; readonly message: string }
  | { readonly tag: "Unauthorized" }
  | { readonly tag: "Forbidden" }
  | { readonly tag: "NotFound" }
  | { readonly tag: "MethodNotAllowed" }
  | { readonly tag: "NotAcceptable" }
  | { readonly tag: "RequestTimeout" }
  | { readonly tag: "Conflict"; readonly message: string }
  | { readonly tag: "Gone" }
  | { readonly tag: "LengthRequired" }
  | { readonly tag: "PayloadTooLarge"; readonly message: string }
  | { readonly tag: "UnsupportedMediaType"; readonly message: string }
  | { readonly tag: "UnprocessableEntity"; readonly message: string }
  | { readonly tag: "TooManyRequests"; readonly message: string }
  | { readonly tag: "UnavailableForLegalReasons"; readonly message: string }
  // 5xx server error.
  | { readonly tag: "ServerError"; readonly message: string }
  | { readonly tag: "NotImplemented"; readonly message: string }
  | { readonly tag: "BadGateway"; readonly message: string }
  | { readonly tag: "ServiceUnavailable"; readonly message: string }
  | { readonly tag: "GatewayTimeout"; readonly message: string }
  // 4xx/5xx with an author-owned body — an error status the author chooses,
  // under its own content-type, no codec (#2341, L4).
  | {
      readonly tag: "RawError";
      readonly status: number;
      readonly body: Uint8Array;
      readonly contentType: string;
    };

export const HttpResult = {
  // 2xx success.
  Ok: <T>(value: T): HttpResult<T> => ({ tag: "Ok", value }),
  // 2xx streamed body — the argument is a stream of SSE event payloads.
  Streaming: (stream: AsyncIterable<string>): HttpResult<never> => ({ tag: "Streaming", stream }),
  // 2xx raw body — the arguments are the octets and their content-type.
  Raw: (body: Uint8Array, contentType: string): HttpResult<never> => ({ tag: "Raw", body, contentType }),
  // 2xx raw body with its validator — the octets, their content-type, and the
  // entity tag the handler supplies (quoted, optionally `W/`-prefixed).
  RawTagged: (body: Uint8Array, contentType: string, etag: string): HttpResult<never> => ({
    tag: "RawTagged",
    body,
    contentType,
    etag,
  }),
  Created: <T>(value: T): HttpResult<T> => ({ tag: "Created", value }),
  Accepted: <T>(value: T): HttpResult<T> => ({ tag: "Accepted", value }),
  NoContent: { tag: "NoContent" } as HttpResult<never>,
  // 3xx redirection — the argument is the target URL (Location header).
  MovedPermanently: (location: string): HttpResult<never> => ({ tag: "MovedPermanently", location }),
  Found: (location: string): HttpResult<never> => ({ tag: "Found", location }),
  SeeOther: (location: string): HttpResult<never> => ({ tag: "SeeOther", location }),
  TemporaryRedirect: (location: string): HttpResult<never> => ({ tag: "TemporaryRedirect", location }),
  PermanentRedirect: (location: string): HttpResult<never> => ({ tag: "PermanentRedirect", location }),
  // 4xx client error.
  BadRequest: (message: string): HttpResult<never> => ({ tag: "BadRequest", message }),
  Unauthorized: { tag: "Unauthorized" } as HttpResult<never>,
  Forbidden: { tag: "Forbidden" } as HttpResult<never>,
  NotFound: { tag: "NotFound" } as HttpResult<never>,
  MethodNotAllowed: { tag: "MethodNotAllowed" } as HttpResult<never>,
  NotAcceptable: { tag: "NotAcceptable" } as HttpResult<never>,
  RequestTimeout: { tag: "RequestTimeout" } as HttpResult<never>,
  Conflict: (message: string): HttpResult<never> => ({ tag: "Conflict", message }),
  Gone: { tag: "Gone" } as HttpResult<never>,
  LengthRequired: { tag: "LengthRequired" } as HttpResult<never>,
  PayloadTooLarge: (message: string): HttpResult<never> => ({ tag: "PayloadTooLarge", message }),
  UnsupportedMediaType: (message: string): HttpResult<never> => ({
    tag: "UnsupportedMediaType",
    message,
  }),
  UnprocessableEntity: (message: string): HttpResult<never> => ({
    tag: "UnprocessableEntity",
    message,
  }),
  TooManyRequests: (message: string): HttpResult<never> => ({ tag: "TooManyRequests", message }),
  UnavailableForLegalReasons: (message: string): HttpResult<never> => ({
    tag: "UnavailableForLegalReasons",
    message,
  }),
  // 5xx server error.
  ServerError: (message: string): HttpResult<never> => ({ tag: "ServerError", message }),
  NotImplemented: (message: string): HttpResult<never> => ({ tag: "NotImplemented", message }),
  BadGateway: (message: string): HttpResult<never> => ({ tag: "BadGateway", message }),
  ServiceUnavailable: (message: string): HttpResult<never> => ({ tag: "ServiceUnavailable", message }),
  GatewayTimeout: (message: string): HttpResult<never> => ({ tag: "GatewayTimeout", message }),
  // 4xx/5xx with an author-owned body — the compiler resolves the status name.
  RawError: (status: number, body: Uint8Array, contentType: string): HttpResult<never> => ({
    tag: "RawError",
    status,
    body,
    contentType,
  }),
};

// Match a path pattern (e.g., "/orders/:id") against a request path.
// Returns the captured parameter map, or null on no match.
export function matchPath(
  pattern: string,
  path: string,
): { params: Record<string, string> } | null {
  const patternSegments = pattern.split("/").filter(Boolean);
  const pathSegments = path.split("/").filter(Boolean);
  if (patternSegments.length !== pathSegments.length) return null;
  const params: Record<string, string> = {};
  for (let i = 0; i < patternSegments.length; i++) {
    const p = patternSegments[i];
    if (p.startsWith(":")) {
      params[p.slice(1)] = decodeURIComponent(pathSegments[i]);
    } else if (p !== pathSegments[i]) {
      return null;
    }
  }
  return { params };
}

// The HTTP status code each HttpResult variant maps to. Kept in sync with
// HTTP_VARIANTS in bynk-syntax/src/ast.rs (the compiler-side source of truth).
// `RawError` carries its own status, so it has no row.
const HTTP_STATUS: Record<Exclude<HttpResult<unknown>["tag"], "RawError">, number> = {
  Ok: 200,
  Streaming: 200,
  Raw: 200,
  RawTagged: 200,
  Created: 201,
  Accepted: 202,
  NoContent: 204,
  MovedPermanently: 301,
  Found: 302,
  SeeOther: 303,
  TemporaryRedirect: 307,
  PermanentRedirect: 308,
  BadRequest: 400,
  Unauthorized: 401,
  Forbidden: 403,
  NotFound: 404,
  MethodNotAllowed: 405,
  NotAcceptable: 406,
  RequestTimeout: 408,
  Conflict: 409,
  Gone: 410,
  LengthRequired: 411,
  PayloadTooLarge: 413,
  UnsupportedMediaType: 415,
  UnprocessableEntity: 422,
  TooManyRequests: 429,
  UnavailableForLegalReasons: 451,
  ServerError: 500,
  NotImplemented: 501,
  BadGateway: 502,
  ServiceUnavailable: 503,
  GatewayTimeout: 504,
};

// Serialise an HttpResult<T> to a Response. The variant determines the HTTP
// status code; success variants carry the value as JSON, redirects emit a
// Location header, error variants carry an `{ error }` body, and the remaining
// statuses are bodyless.
// Frame a stream of event payloads as an SSE (`text/event-stream`) Response.
// Each stream element is one SSE event; a multi-line element becomes multiple
// `data:` lines, terminated by a blank line. The body is a ReadableStream, so
// this is a Web standard that runs unchanged on Workers and Node.
function sseResponse(stream: AsyncIterable<string>): Response {
  const encoder = new TextEncoder();
  // v0.139 (ADR 0162): a `pull` source with `highWaterMark: 0` makes the body
  // lazy — the source stream is advanced only when a reader pulls, never
  // eagerly at construction. So a `Streaming` `GET` answered as `HEAD` (whose
  // `Response` body is discarded unread) never advances the source at all, and a
  // real `GET` streams under the consumer's backpressure rather than buffering
  // the whole stream up front. `cancel` returns the iterator so an abandoned
  // read releases the source promptly.
  const iterator = stream[Symbol.asyncIterator]();
  const body = new ReadableStream<Uint8Array>(
    {
      async pull(controller) {
        const { value, done } = await iterator.next();
        if (done) {
          controller.close();
          return;
        }
        for (const line of value.split("\n")) {
          controller.enqueue(encoder.encode(`data: ${line}\n`));
        }
        controller.enqueue(encoder.encode("\n"));
      },
      async cancel(reason) {
        await iterator.return?.(reason);
      },
    },
    { highWaterMark: 0 },
  );
  return new Response(body, {
    status: 200,
    headers: { "content-type": "text/event-stream", "cache-control": "no-cache" },
  });
}

export function httpResultToResponse<T>(
  result: HttpResult<T>,
  serialiseValue: (v: T) => JsonValue,
  opts?: { readonly weakEtag?: boolean },
): Response {
  // #2341 (L4): an author-chosen error status with an author-owned body.
  if (result.tag === "RawError") {
    return new Response(result.body as BodyInit, {
      status: result.status,
      headers: { "content-type": result.contentType },
    });
  }
  const status = HTTP_STATUS[result.tag];
  switch (result.tag) {
    // 2xx with a body — the serialised value as JSON.
    case "Ok":
    case "Created":
    case "Accepted": {
      const body = JSON.stringify(serialiseValue(result.value));
      const headers: Record<string, string> = { "content-type": "application/json" };
      // v0.140 (ADR 0163): an eligible `GET` `Ok` carries a weak validator over its
      // serialised body, so a conditional re-fetch can be answered `304`. Of the
      // JSON variants only `Ok` (the success read) is eligible (DECISION B) — a
      // small `Raw` body is the other automatic case, below — and only when the caller
      // opts in — the `GET` dispatch site passes `weakEtag`, so a POST/PUT `Ok` (or
      // any other method) stays byte-for-byte unchanged.
      if (opts?.weakEtag && result.tag === "Ok") {
        headers["etag"] = weakETag(body);
      }
      return new Response(body, { status, headers });
    }
    // 200 with a streamed body — each stream element is one SSE event.
    case "Streaming":
      return sseResponse(result.stream);
    // 200 with a raw body — author-owned bytes with an explicit content-type.
    // No codec runs; the Uint8Array is written straight into the Response. The
    // `as BodyInit` cast satisfies TS 5.7, whose `Uint8Array<ArrayBufferLike>`
    // no longer matches DOM's `BufferSource` (it excludes SharedArrayBuffer) —
    // a bare Uint8Array is a valid body at runtime on both Workers and Node.
    // Caching raw responses: on a `GET` (the `weakEtag` opt-in), a body of at most
    // `RAW_WEAK_ETAG_MAX_BYTES` carries a weak validator over its octets, as a JSON
    // `Ok` does; a larger one carries none, so the hash never costs more than a
    // bounded slice of the Worker's CPU. A large body gets its validator from the
    // handler instead, through `RawTagged`.
    case "Raw": {
      const headers: Record<string, string> = { "content-type": result.contentType };
      if (opts?.weakEtag && result.body.byteLength <= RAW_WEAK_ETAG_MAX_BYTES) {
        headers["etag"] = weakETagBytes(result.body);
      }
      return new Response(result.body as BodyInit, { status: 200, headers });
    }
    // 200 with a raw body and the handler's own validator, sent as the `ETag`
    // without hashing, whatever the body's size and method. A malformed tag throws,
    // so the dispatch's fault path answers `500` and logs the route — never a
    // malformed header on the wire.
    case "RawTagged":
      if (!isEntityTag(result.etag)) {
        throw new Error(
          `RawTagged: ${JSON.stringify(result.etag)} is not an entity tag ` +
            `(RFC 9110 §8.8.3: quoted, optionally W/-prefixed, e.g. "v1" or W/"v1")`,
        );
      }
      return new Response(result.body as BodyInit, {
        status: 200,
        headers: { "content-type": result.contentType, etag: result.etag },
      });
    // 3xx — bodyless, with the target URL in the Location header.
    case "MovedPermanently":
    case "Found":
    case "SeeOther":
    case "TemporaryRedirect":
    case "PermanentRedirect":
      return new Response(null, { status, headers: { location: result.location } });
    // Error variants carrying an explanatory message — `{ error }` JSON body.
    case "BadRequest":
    case "Conflict":
    case "PayloadTooLarge":
    case "UnsupportedMediaType":
    case "UnprocessableEntity":
    case "TooManyRequests":
    case "UnavailableForLegalReasons":
    case "ServerError":
    case "NotImplemented":
    case "BadGateway":
    case "ServiceUnavailable":
    case "GatewayTimeout":
      return new Response(JSON.stringify({ error: result.message }), {
        status,
        headers: { "content-type": "application/json" },
      });
    // Self-describing statuses — bodyless.
    case "NoContent":
    case "Unauthorized":
    case "Forbidden":
    case "NotFound":
    case "MethodNotAllowed":
    case "NotAcceptable":
    case "RequestTimeout":
    case "Gone":
    case "LengthRequired":
      return new Response(null, { status });
  }
}

// v0.139 (ADR 0162): rebuild a `GET` response as its `HEAD` answer — identical
// status and headers, empty body (RFC 9110 §9.3.2). `Response.body` is not
// re-read: passing `null` discards the original body without consuming it, so a
// `Streaming` (`SSE`) `GET` answered as `HEAD` returns the stream's headers while
// its `ReadableStream` is never started or drained. `content-length` is omitted
// (the body is never materialised — permitted, §9.3.2 "MAY").
export function headResponse(response: Response): Response {
  return new Response(null, { status: response.status, headers: response.headers });
}

// testing-the-boundary Slice B: the inverse of `httpResultToResponse` for a
// `system`-tier test. A case drives a route with a real `fetch` and asserts on
// the returned `HttpResult[T]` (`expect item is Created(_)`), so the harness
// decodes the `Response` back through this. Status is the discriminator: it
// picks the canonical variant for each code (a 200 body decodes to `Ok`;
// `Streaming`/`Raw` — both 200 — are not distinguished, since a test asserting
// on those would use the unit tier). Value-bearing 2xx parse the JSON body
// through `deserialiseValue`; error variants recover their `{ error }` message;
// redirects recover the `Location` header; the rest are bodyless.
const STATUS_TO_TAG: Record<number, HttpResult<unknown>["tag"]> = {
  200: "Ok",
  201: "Created",
  202: "Accepted",
  204: "NoContent",
  301: "MovedPermanently",
  302: "Found",
  303: "SeeOther",
  307: "TemporaryRedirect",
  308: "PermanentRedirect",
  400: "BadRequest",
  401: "Unauthorized",
  403: "Forbidden",
  404: "NotFound",
  405: "MethodNotAllowed",
  406: "NotAcceptable",
  408: "RequestTimeout",
  409: "Conflict",
  410: "Gone",
  411: "LengthRequired",
  413: "PayloadTooLarge",
  415: "UnsupportedMediaType",
  422: "UnprocessableEntity",
  429: "TooManyRequests",
  451: "UnavailableForLegalReasons",
  500: "ServerError",
  501: "NotImplemented",
  502: "BadGateway",
  503: "ServiceUnavailable",
  504: "GatewayTimeout",
};

export async function responseToHttpResult<T>(
  response: Response,
  deserialiseValue: (json: JsonValue) => Result<T, BoundaryError>,
): Promise<HttpResult<T>> {
  const tag = STATUS_TO_TAG[response.status] ?? "ServerError";
  switch (tag) {
    case "Ok":
    case "Created":
    case "Accepted": {
      const json = (await response.json()) as JsonValue;
      const decoded = deserialiseValue(json);
      const value = (decoded.tag === "Ok" ? decoded.value : (json as unknown)) as T;
      return { tag, value };
    }
    case "MovedPermanently":
    case "Found":
    case "SeeOther":
    case "TemporaryRedirect":
    case "PermanentRedirect":
      return { tag, location: response.headers.get("location") ?? "" };
    case "BadRequest":
    case "Conflict":
    case "PayloadTooLarge":
    case "UnsupportedMediaType":
    case "UnprocessableEntity":
    case "TooManyRequests":
    case "UnavailableForLegalReasons":
    case "ServerError":
    case "NotImplemented":
    case "BadGateway":
    case "ServiceUnavailable":
    case "GatewayTimeout": {
      let message = "";
      try {
        const body = (await response.json()) as { error?: string };
        message = body.error ?? "";
      } catch {
        message = "";
      }
      return { tag, message } as HttpResult<T>;
    }
    default:
      // NoContent and the self-describing bodyless statuses.
      return { tag } as HttpResult<T>;
  }
}

// Slice C (testing-the-boundary): the outcome of a `system`-tier address driven
// with a raw `Wire(…)` argument. A boundary rejection never produces an
// `HttpResult` (the handler never ran), so a `Wire`-carrying call yields this
// sum instead: `Rejected(detail)` when the router refused the input before the
// handler, or `Handled(httpResult)` when it ran. The rejection `detail` carries a
// `tag` mirroring the router's `BoundaryError.kind` (`RefinementViolation`,
// `MalformedJson`, `StructuralMismatch`), so `expect r is Rejected(
// RefinementViolation(_))` lowers to a plain `.tag` test. #1934: the checker
// types it as `HttpOutcome[T]`, and every rejection carries `detail`: for a body
// or path rejection the router's description of what it refused, which
// `RefinementViolation(d)` binds (`BOUNDARY_REJECTIONS` in
// `bynk-check/src/checker.rs`), and `""` for the seam's and router's refusals.
export type HttpOutcome<T> =
  | {
      readonly tag: "Rejected";
      readonly value: { readonly tag: string; readonly detail: string; readonly [k: string]: unknown };
    }
  | { readonly tag: "Handled"; readonly value: HttpResult<T> };

// #1934: the one-line description a `Rejected` body or path rejection carries
// as `detail`, from the router's `BoundaryError` body.
function rejectionDetail(body: Record<string, unknown>): string {
  const str = (v: unknown): string => (typeof v === "string" ? v : "");
  switch (body.kind) {
    case "MalformedJson":
    case "PayloadTooLarge":
    case "UnsupportedMediaType":
      return str(body.details);
    case "StructuralMismatch":
      return `${str(body.path)}: expected ${str(body.expected)}, got ${str(body.actual)}`;
    case "RefinementViolation": {
      const violation = body.violation as { message?: unknown } | undefined;
      return `${str(body.path)}: ${str(violation?.message)}`;
    }
    default:
      return "";
  }
}

// #2341 (decision C): the rejection a router-synthesised response stands for,
// read from its status and body — what `on rejected` receives. Only the
// router's own refusals reach this (a handler's responses never do), so a `401`
// or `405` here is the seam's or the router's. `null` for anything else (the
// `204` to `OPTIONS`).
async function rejectionOf(
  response: Response,
): Promise<{ readonly tag: string; readonly detail: string } | null> {
  if (response.status === 401) return { tag: "Unauthorized", detail: "" };
  if (response.status === 405) return { tag: "MethodNotAllowed", detail: "" };
  if (response.status !== 400 && response.status !== 413 && response.status !== 415) return null;
  let body: Record<string, unknown> | null = null;
  try {
    body = (await response.clone().json()) as Record<string, unknown>;
  } catch {
    body = null;
  }
  if (body === null || typeof body.kind !== "string") return null;
  return { tag: body.kind, detail: rejectionDetail(body) };
}

// #2341 (decision C): render a router rejection through a service's
// `on rejected`. The status is the rejection's own, so the hook's answer is
// used only when it is a `RawError` of that status; anything else — another
// variant, another status, or a fault in the hook — falls back to the router's
// default response, and is reported. The default's other headers (`Allow` on
// a `405`) are kept.
export async function renderRejection(
  response: Response,
  hook: (why: { readonly tag: string; readonly detail: string }) => Promise<HttpResult<unknown>>,
): Promise<Response> {
  const why = await rejectionOf(response);
  if (why === null) return response;
  let result: HttpResult<unknown>;
  try {
    result = await hook(why);
  } catch (e) {
    console.error(`bynk: \`on rejected\` faulted rendering a ${response.status}; the default response was sent`, e);
    return response;
  }
  if (result.tag !== "RawError" || result.status !== response.status) {
    const got = result.tag === "RawError" ? `RawError(${result.status}, …)` : result.tag;
    console.warn(
      `bynk: \`on rejected\` answered ${got} to a ${response.status} ${why.tag}; it must be a RawError of status ${response.status}, so the default response was sent`,
    );
    return response;
  }
  const headers = new Headers(response.headers);
  headers.delete("content-length");
  headers.set("content-type", result.contentType);
  return new Response(result.body as BodyInit, { status: result.status, headers });
}

// The `BoundaryError.kind`s the router emits when it refuses input *before* the
// handler — the only shapes that make an outcome `Rejected`. Kept in sync with
// the router's rejection bodies in `workers_entry.rs`.
const BOUNDARY_REJECTION_KINDS = new Set(["RefinementViolation", "MalformedJson", "StructuralMismatch"]);

// Whether `request`'s `Content-Type` is the media type a `@raw` route declares:
// parameters (`; charset=…`) are not part of the match, the comparison is
// case-insensitive, `"*/*"` accepts anything, and a missing header matches only
// that wildcard.
export function mediaTypeMatches(request: Request, declared: string): boolean {
  if (declared === "*/*") return true;
  const given = request.headers.get("content-type");
  if (given === null) return false;
  return given.split(";")[0].trim().toLowerCase() === declared.toLowerCase();
}

// #2341 (decision A): an HTTP handler's `headers: RequestHeaders` — a read-only
// view of the request's headers. `get` is case-insensitive and joins repeated
// headers with ", " (both the platform `Headers.get` contract); `bearer` is the
// token of an `Authorization: Bearer <token>` header and nothing else;
// `clientIp` is the address Cloudflare reports (`CF-Connecting-IP`, which
// `wrangler dev` sets too).
export interface RequestHeaders {
  get(name: string): Option<string>;
  bearer(): Option<string>;
  clientIp(): Option<string>;
}

/** #2341 (L4): the request's headers, or — in a test — `"name: value"` lines
 *  (`RequestHeaders.of`); a line without a colon is ignored. */
export function requestHeaders(source: Request | readonly string[]): RequestHeaders {
  let headers: Headers;
  if (source instanceof Request) {
    headers = source.headers;
  } else {
    headers = new Headers();
    for (const line of source) {
      const i = line.indexOf(":");
      if (i > 0) headers.append(line.slice(0, i).trim(), line.slice(i + 1).trim());
    }
  }
  const opt = (v: string | null): Option<string> =>
    v === null ? { tag: "None" } : { tag: "Some", value: v };
  const view: RequestHeaders = {
    get: (name: string) => opt(headers.get(name)),
    bearer: () => {
      const m = /^Bearer +([^\s]+) *$/i.exec(headers.get("authorization") ?? "");
      return m === null ? { tag: "None" } : { tag: "Some", value: m[1] };
    },
    clientIp: () => opt(headers.get("cf-connecting-ip")),
  };
  // The system-tier driver sends a test's headers on its real request.
  Object.defineProperty(view, REQUEST_HEADER_PAIRS, { value: headers, enumerable: false });
  return view;
}

const REQUEST_HEADER_PAIRS = Symbol("bynk.requestHeaderPairs");

/** #2341 (L4): a `RequestHeaders`' own headers as a plain record — what a
 *  system-tier driver spreads into the request it sends. */
export function requestHeaderPairs(view: RequestHeaders): Record<string, string> {
  const headers = (view as unknown as Record<symbol, Headers | undefined>)[REQUEST_HEADER_PAIRS];
  const out: Record<string, string> = {};
  headers?.forEach((v, k) => {
    out[k] = v;
  });
  return out;
}

export async function responseToHttpOutcome<T>(
  response: Response,
  deserialiseValue: (json: JsonValue) => Result<T, BoundaryError>,
): Promise<HttpOutcome<T>> {
  // Classify on the body's *shape*, not its status. A pre-handler rejection is a
  // `400` whose body is a `BoundaryError` carrying a recognised `kind`. A
  // handler that *ran* and returned `BadRequest(msg)` also yields a `400`, but
  // its body is `{ error: msg }` with no `kind` — the handler produced it, so it
  // is `Handled`, not `Rejected`. Reading `kind` (rather than the status) is what
  // keeps "the handler never ran" — the whole meaning of `Rejected` — accurate.
  if (response.status === 400) {
    let body: { kind?: unknown } | null = null;
    try {
      body = (await response.clone().json()) as { kind?: unknown };
    } catch {
      body = null;
    }
    if (body && typeof body.kind === "string" && BOUNDARY_REJECTION_KINDS.has(body.kind)) {
      const fields = body as Record<string, unknown>;
      return {
        tag: "Rejected",
        value: { ...fields, tag: body.kind, detail: rejectionDetail(fields) },
      };
    }
    // No boundary `kind` → the handler produced this `400`; fall through.
  }
  // A capped route's `413` and a raw route's `415` are the router's own
  // synthesised refusals, told from a handler's `PayloadTooLarge`/
  // `UnsupportedMediaType` (whose body is `{ error }`) by the `kind` they carry.
  if (response.status === 413 || response.status === 415) {
    let body: { kind?: unknown } | null = null;
    try {
      body = (await response.clone().json()) as { kind?: unknown };
    } catch {
      body = null;
    }
    if (body && (body.kind === "PayloadTooLarge" || body.kind === "UnsupportedMediaType")) {
      const fields = body as Record<string, unknown>;
      return {
        tag: "Rejected",
        value: { ...fields, tag: body.kind, detail: rejectionDetail(fields) },
      };
    }
  }
  // #707: a `405` is `Rejected(MethodNotAllowed)` only when it is the router's
  // *method fall-through* — a live path reached under a method it declares no
  // handler for. Classify on shape, not status: the router synthesises that 405
  // with an `Allow` header (`workers_entry.rs`), whereas a handler that ran and
  // returned `HttpResult.MethodNotAllowed` yields a bodyless 405 with no `Allow`
  // — the handler produced it, so it stays `Handled`. Same shape-vs-status care
  // as the `400` (`kind` body) path.
  if (response.status === 405 && response.headers.has("allow")) {
    return { tag: "Rejected", value: { tag: "MethodNotAllowed", detail: "" } };
  }
  const handled = await responseToHttpResult(response, deserialiseValue);
  return { tag: "Handled", value: handled };
}

// #706: the outcome of driving a secured route with *no credential* (`by
// Nobody`). A `401` here is the auth seam refusing the request before the
// handler ran — `Rejected(Unauthorized)` — which is unambiguous *because the
// caller sent no credential* (unlike the shared `responseToHttpOutcome`, where a
// `401` could be a handler-returned `Unauthorized`, so it stays `Handled`). Any
// other status is decoded normally: a route that is not actually secured lets
// the request through, and the case observes `Handled` rather than a false
// `Rejected`.
export async function responseToUnauthOutcome<T>(
  response: Response,
  deserialiseValue: (json: JsonValue) => Result<T, BoundaryError>,
): Promise<HttpOutcome<T>> {
  if (response.status === 401) {
    return { tag: "Rejected", value: { tag: "Unauthorized", detail: "" } };
  }
  return responseToHttpOutcome(response, deserialiseValue);
}

// v0.131 (ADR 0159): the cross-origin (CORS) policy a `from http` service carries
// via its `cors { }` section. The compiler synthesises one of these per
// CORS-enabled service and threads it into the entry router. `allowMethods` is
// derived from the service's routes at emit time (never restated by the author);
// `allowHeaders` carries the resolved list (the `content-type`/`Authorization`
// default, or the author's override). `maxAgeSecs` is the `Access-Control-Max-Age`
// in whole seconds, absent when the author gave no `maxAge`.
export interface CorsPolicy {
  readonly origins: readonly string[];
  readonly allowMethods: readonly string[];
  readonly allowHeaders: readonly string[];
  readonly credentials: boolean;
  readonly maxAgeSecs: number | null;
}

// Resolve the `Access-Control-Allow-Origin` value for a request, given the
// policy and the request's `Origin` header. A wildcard policy (`["*"]`) answers
// every origin with `*` (and needs no `Vary`, since the response does not depend
// on the request origin). A concrete allowlist **reflects** the request's origin
// when it matches — never echoes an unvalidated value — and returns `null` on no
// match, so the caller omits the header and the browser fails the request closed.
function corsResolveOrigin(policy: CorsPolicy, requestOrigin: string | null): string | null {
  if (policy.origins.length === 1 && policy.origins[0] === "*") return "*";
  if (requestOrigin !== null && policy.origins.includes(requestOrigin)) return requestOrigin;
  return null;
}

// Stamp the CORS response headers onto an already-built `Response`, in place.
// `Response.headers` is mutable, so this works uniformly across every
// `httpResultToResponse` shape — JSON, `Raw` bytes, a redirect, an error body,
// or an SSE `ReadableStream` — without reconstructing the response or touching
// its body. When the origin does not match the allowlist, no ACAO is added (the
// browser blocks the read); a reflected origin also gets `Vary: Origin` so a
// shared cache never serves one origin's grant to another.
export function applyCors<R extends Response>(
  response: R,
  policy: CorsPolicy,
  requestOrigin: string | null,
): R {
  const allowOrigin = corsResolveOrigin(policy, requestOrigin);
  if (allowOrigin === null) return response;
  response.headers.set("access-control-allow-origin", allowOrigin);
  if (allowOrigin !== "*") response.headers.append("vary", "Origin");
  if (policy.credentials) response.headers.set("access-control-allow-credentials", "true");
  return response;
}

// Build the `204 No Content` preflight response for an `OPTIONS` request against
// a CORS-enabled route. Answered by the entry router *before* the auth seam — a
// preflight is credential-less by spec, so it must not be rejected by a `by`
// actor / Bearer check. A non-allowlisted origin still gets a bodyless `204`, but
// without the `Access-Control-*` grant, so the browser's preflight check fails
// closed.
export function corsPreflightResponse(policy: CorsPolicy, requestOrigin: string | null): Response {
  const headers = new Headers();
  const allowOrigin = corsResolveOrigin(policy, requestOrigin);
  if (allowOrigin !== null) {
    headers.set("access-control-allow-origin", allowOrigin);
    if (allowOrigin !== "*") headers.append("vary", "Origin");
    if (policy.credentials) headers.set("access-control-allow-credentials", "true");
    headers.set("access-control-allow-methods", policy.allowMethods.join(", "));
    headers.set("access-control-allow-headers", policy.allowHeaders.join(", "));
    if (policy.maxAgeSecs !== null) {
      headers.set("access-control-max-age", String(policy.maxAgeSecs));
    }
  }
  return new Response(null, { status: 204, headers });
}

// v0.141 (ADR 0164): the security-headers policy a `from http` service carries
// via its `security { }` section. Unlike CORS, the compiler synthesises one of
// these for *every* `from http` service (not only those with a block), because
// the safe header is on by default — a service with no `security { }` still gets
// `{ nosniff: true, hstsMaxAgeSecs: null }`. `nosniff` stamps
// `X-Content-Type-Options: nosniff` (a JSON/text body a browser must not
// MIME-sniff into HTML); `hstsMaxAgeSecs`, when non-null, stamps
// `Strict-Transport-Security: max-age=…` (the opt-in HTTPS pin).
export interface SecurityPolicy {
  readonly nosniff: boolean;
  readonly hstsMaxAgeSecs: number | null;
}

// Stamp the security response headers onto an already-built `Response`, in place
// — the `applyCors` shape. `Response.headers` is mutable, so this works
// uniformly across every response family (JSON, `Raw` bytes, a redirect, an
// error body, an SSE stream, and the synthesised preflight / `405` / `304`).
// Composes with `applyCors`: the two set **disjoint** headers, so stamping order
// is irrelevant. `set` (not `append`) is idempotent and last-writer-wins, so a
// header also set at the edge (e.g. Cloudflare) is simply overwritten with the
// policy's value.
export function applySecurityHeaders<R extends Response>(
  response: R,
  policy: SecurityPolicy,
): R {
  if (policy.nosniff) response.headers.set("x-content-type-options", "nosniff");
  if (policy.hstsMaxAgeSecs !== null) {
    response.headers.set("strict-transport-security", `max-age=${policy.hstsMaxAgeSecs}`);
  }
  return response;
}

// v0.140 (ADR 0163): a **weak** validator over a response's serialised body, from
// a fast non-cryptographic hash (FNV-1a, 32-bit). Weak (`W/"…"`) is correct here —
// the guarantee is *semantic* equivalence of the representation, which weak
// validators exist for, and Bynk serves no byte-range requests (the one place a
// strong validator is required). Synchronous, so `httpResultToResponse` stays sync
// (no `await crypto.subtle`); a stronger hash (SHA-256) is a drop-in swap behind
// this name if ever needed.
export function weakETag(body: string): string {
  // FNV-1a over the string's UTF-16 code units. The exact byte basis is immaterial
  // to correctness — a validator only has to *change when the body changes* — so
  // hashing code units directly avoids a `TextEncoder` allocation on the hot path.
  let hash = 0x811c9dc5;
  for (let i = 0; i < body.length; i++) {
    hash ^= body.charCodeAt(i);
    // `* 16777619` (the FNV prime) in 32-bit via `Math.imul`.
    hash = Math.imul(hash, 0x01000193);
  }
  // `>>> 0` to an unsigned 32-bit; base-36 for a compact opaque token.
  return `W/"${(hash >>> 0).toString(36)}"`;
}

// Caching raw responses: the largest `Raw` body that gets the automatic weak
// `ETag` — 1 MiB. Hashing is synchronous and proportional to the body, so above
// this a `GET` carries no automatic validator; the handler supplies one through
// `RawTagged` instead.
export const RAW_WEAK_ETAG_MAX_BYTES = 1024 * 1024;

// Caching raw responses: `weakETag`'s FNV-1a, over a `Raw` body's octets, in the
// same `W/"<base36>"` form.
function weakETagBytes(body: Uint8Array): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < body.length; i++) {
    hash ^= body[i];
    hash = Math.imul(hash, 0x01000193);
  }
  return `W/"${(hash >>> 0).toString(36)}"`;
}

// Caching raw responses: an entity tag as RFC 9110 §8.8.3 writes it — an optional
// `W/` and a double-quoted run of `etagc` (`%x21 / %x23-7E`). The grammar's
// `obs-text` is left out, so every accepted tag is also a valid header value.
function isEntityTag(tag: string): boolean {
  return /^(W\/)?"[\x21\x23-\x7E]*"$/.test(tag);
}

// v0.140 (ADR 0163): stamp a `Cache-Control` freshness directive onto an
// already-built `Response`, in place — the opt-in half of caching, driven by a
// handler's `@cache(maxAge:, scope:)` annotation. `scope` is the author's
// `public`/`private` (default `private`, so a *shared* cache never stores unless
// the author opts in); `maxAgeSecs` is `maxAge` in whole seconds. Only called for
// a `GET` that carries `@cache`; a route without it emits no `Cache-Control` and
// stays revalidatable through its `ETag` alone. `immutable` (caching raw
// responses, RFC 8246) appends the directive: the author's promise that the
// representation at this URL never changes, so no cache revalidates it within
// `max-age`. The dispatch passes it only when `true`.
export function applyCache<R extends Response>(
  response: R,
  maxAgeSecs: number,
  scope: "public" | "private",
  immutable?: boolean,
): R {
  const directives = `${scope}, max-age=${maxAgeSecs}`;
  response.headers.set("cache-control", immutable ? `${directives}, immutable` : directives);
  return response;
}

// v0.140 (ADR 0163): the conditional-`GET` router decision. When the built
// response carries a weak `ETag` and the request's `If-None-Match` lists a
// matching validator, answer `304 Not Modified` with an empty body, copying the
// `ETag` and any `Cache-Control` across (RFC 9110 §15.4.5 — a `304` carries the
// caching headers a `200` would have). Otherwise the response passes through
// untouched. Like the CORS preflight and the method-semantics `405`, the `304` is
// a *router* response synthesised from the request validator, never an
// `HttpResult` variant (ADR 0126 D4). Runs *after* the handler (the body must
// exist to hash), so it saves bandwidth, not server work.
export function notModifiedIfMatch<R extends Response>(
  response: R,
  request: Request,
): R | Response {
  const etag = response.headers.get("etag");
  if (etag === null) return response;
  const ifNoneMatch = request.headers.get("if-none-match");
  if (ifNoneMatch === null) return response;
  if (!ifNoneMatchMatches(ifNoneMatch, etag)) return response;
  const headers = new Headers();
  headers.set("etag", etag);
  const cacheControl = response.headers.get("cache-control");
  if (cacheControl !== null) headers.set("cache-control", cacheControl);
  return new Response(null, { status: 304, headers });
}

// RFC 9110 §13.1.2: `If-None-Match` is a comma-separated list of entity tags (or a
// bare `*`, matching any current representation), compared with the **weak**
// comparison function — the `W/` prefix is ignored on both sides. Our validators
// are always weak and a conditional client echoes back exactly what we sent, but
// handling the list, `*`, and weak comparison keeps this correct against any
// conformant client.
//
// The list is tokenised by entity tag, not split on `,`: a handler-supplied
// `RawTagged` tag may itself contain a comma (`etagc` admits `%x2C`), so
// `"a,b"` must stay one tag.
function ifNoneMatchMatches(headerValue: string, etag: string): boolean {
  const target = stripWeakPrefix(etag);
  for (const [candidate] of headerValue.matchAll(/\*|(?:W\/)?"[^"]*"/g)) {
    if (candidate === "*") return true;
    if (stripWeakPrefix(candidate) === target) return true;
  }
  return false;
}

function stripWeakPrefix(tag: string): string {
  return tag.startsWith("W/") ? tag.slice(2) : tag;
}

// v0.44: QueueResult — the built-in queue verdict sum (non-generic). `Ack`
// confirms the message; `Retry` redelivers it, carrying a reason for the log.
export type QueueResult =
  | { readonly tag: "Ack" }
  | { readonly tag: "Retry"; readonly reason: string };

export const QueueResult = {
  Ack: { tag: "Ack" } as QueueResult,
  Retry: (reason: string): QueueResult => ({ tag: "Retry", reason }),
};

// v0.9.2: agent instantiation + per-key state lifecycle.
//
// An agent keyed by some value lowers to a *lookup-or-create* of the durable
// state for that key. In bundle mode the per-agent `StateRegistry` holds an
// in-memory `DurableObjectState` per serialised key (same key → same state
// within a session; reset per test). In workers mode the agent is a Durable
// Object: `makeWorkersAgent` returns a typed proxy over the DO stub whose
// method calls route through `callDurableObjectMethod`. `makeAgent` picks the
// path: a present binding means workers, an absent one means bundle.

// A minimal structural view of the Cloudflare Durable Object namespace/stub
// surface. The real runtime is richer but structurally compatible.
export interface DurableObjectStub {
  fetch(input: string, init?: unknown): Promise<Response>;
}

export interface DurableObjectNamespace {
  idFromName(name: string): unknown;
  get(id: unknown): DurableObjectStub;
}

// Serialise an agent key to a stable string. Two semantically-equal keys must
// serialise identically: a string is itself, a primitive is its JSON form, a
// record is canonical JSON with sorted fields.
export function serialiseAgentKey(value: unknown): string {
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean" || value === null) {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return JSON.stringify(value.map((v) => serialiseAgentKey(v)));
  }
  if (typeof value === "object") {
    const obj = value as { [k: string]: unknown };
    const keys = Object.keys(obj).sort();
    return JSON.stringify(keys.map((k) => [k, serialiseAgentKey(obj[k])]));
  }
  return JSON.stringify(value);
}

// Per-agent registry: serialised key → in-memory durable state. Used in bundle
// mode (and in `bynkc test`). `reset()` clears every state so a fresh test
// sees a clean slate.
export class StateRegistry<K> {
  private states = new Map<string, DurableObjectState>();

  getOrCreate(key: K): DurableObjectState {
    const sk = serialiseAgentKey(key);
    let state = this.states.get(sk);
    if (state === undefined) {
      state = makeTestState(sk);
      this.states.set(sk, state);
    }
    return state;
  }

  reset(): void {
    this.states.clear();
  }
}

// #1678 (runtime-semantics track S11): on the workers target an agent call
// crosses a Durable Object `fetch`, so its arguments and result are on a wire.
// They go through the boundary codec, the same `serialise_*`/`deserialise_*`
// helpers a cross-context call uses, so a value whose in-memory shape is not
// JSON-faithful (`Bytes`, a value `Map`, a non-finite `Float`) survives the
// trip. The emitter generates one `AgentWire` table per agent: for each handler,
// a codec per parameter and one for the result. Both ends read the same table:
// the caller's proxy encodes arguments and decodes the result, and the DO's
// `fetch` decodes arguments and encodes the result.

// One wire position's codec. `enc` takes the position's in-memory value; it is
// typed `never` so any concrete serialiser (`(value: Blob) => JsonValue`) fits.
export interface WireCodec {
  readonly enc: (value: never) => JsonValue;
  readonly dec: (json: JsonValue, path?: string) => Result<unknown, BoundaryError>;
}

export interface AgentWireMethod {
  readonly args: readonly WireCodec[];
  readonly result: WireCodec;
}

export type AgentWire = Readonly<Record<string, AgentWireMethod>>;

// A position whose type has no wire form (a held `Connection`, a function, a
// `Stream`, a `Query`) passes through as it did before #1678.
export const AGENT_WIRE_PASS: WireCodec = {
  enc: (value: never) => value as JsonValue,
  dec: (json: JsonValue) => Ok(json),
};

function agentWireMethod(wire: AgentWire, method: string): AgentWireMethod {
  // `hasOwn`: a method name comes off the request path.
  if (!Object.hasOwn(wire, method)) {
    throw new Error(`agent method \`${method}\` has no wire codec`);
  }
  return wire[method];
}

// The DO side: decode a call's arguments. A decode failure is an internal
// fault (the caller is the program itself, not an untrusted client), so it
// throws, and the DO's `fetch` fails with a 500 the caller rethrows.
export function decodeAgentArgs(wire: AgentWire, method: string, args: unknown[]): unknown[] {
  const m = agentWireMethod(wire, method);
  return args.map((a, i) => {
    const r = (m.args[i] ?? AGENT_WIRE_PASS).dec(a as JsonValue, `$.args[${i}]`);
    if (r.tag === "Err") throw boundaryError(r.error);
    return r.value;
  });
}

// #1818: the DO side of an agent that reads its own key (`self.<key>`). A
// Durable Object knows only its id, not the key it was addressed by, so the
// caller's proxy sends the key with each call, encoded by the key type's codec,
// and the DO decodes it here.
export function decodeAgentKey(codec: WireCodec, json: unknown): unknown {
  const r = codec.dec(json as JsonValue, "$.key");
  if (r.tag === "Err") throw boundaryError(r.error);
  return r.value;
}

// The DO side: encode a call's result.
export function encodeAgentResult(wire: AgentWire, method: string, result: unknown): JsonValue {
  return agentWireMethod(wire, method).result.enc(result as never);
}

// Workers-mode agent method call: route through the DO stub's `fetch` under
// the `/_bynk/agent/<method>` wire protocol. `args` are already encoded, and
// the result comes back as raw JSON for the caller to decode.
export async function callDurableObjectMethod(
  stub: DurableObjectStub,
  method: string,
  args: unknown[],
  deps: unknown,
  key?: JsonValue,
): Promise<JsonValue> {
  const response = await stub.fetch(`https://_bynk/_bynk/agent/${method}`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    // #1818: the key rides along only for an agent that reads it.
    body: JSON.stringify(key === undefined ? { args, deps } : { args, deps, key }),
  });
  if (!response.ok) throw new Error(await response.text());
  return (await response.json()) as JsonValue;
}

// Workers-mode agent: a typed proxy over the DO stub. Each method access
// returns a function that splits its final argument off as `deps` and routes
// the rest as method args through `callDurableObjectMethod`. The `as C` cast
// gives call sites the agent's real method signatures, so user code reads
// identically to bundle mode.
export function makeWorkersAgent<C>(
  binding: DurableObjectNamespace,
  key: unknown,
  wire?: AgentWire,
  keyCodec?: WireCodec,
): C {
  const stub = binding.get(binding.idFromName(serialiseAgentKey(key)));
  // Encoded per call, not here, so a key that cannot encode fails at the call,
  // as an argument that cannot encode does.
  const sentKey = (): JsonValue | undefined =>
    keyCodec === undefined ? undefined : keyCodec.enc(key as never);
  const proxy = new Proxy(
    {},
    {
      get(_target, prop: string | symbol) {
        if (typeof prop !== "string") return undefined;
        return async (...callArgs: unknown[]) => {
          const deps = callArgs.length > 0 ? callArgs[callArgs.length - 1] : {};
          const args = callArgs.length > 0 ? callArgs.slice(0, -1) : [];
          if (wire === undefined) return callDurableObjectMethod(stub, prop, args, deps, sentKey());
          const m = agentWireMethod(wire, prop);
          const encoded = args.map((a, i) => (m.args[i] ?? AGENT_WIRE_PASS).enc(a as never));
          const json = await callDurableObjectMethod(stub, prop, encoded, deps, sentKey());
          const r = m.result.dec(json);
          if (r.tag === "Err") throw boundaryError(r.error);
          return r.value;
        };
      },
    },
  );
  return proxy as C;
}

// Single agent-construction helper. A present DO binding selects the workers
// path; otherwise the bundle registry path. Call sites are identical across
// targets.
export function makeAgent<C>(
  registry: StateRegistry<unknown>,
  binding: DurableObjectNamespace | undefined,
  key: unknown,
  constructBundle: (state: DurableObjectState) => C,
  wire?: AgentWire,
  keyCodec?: WireCodec,
): C {
  if (binding !== undefined) {
    return makeWorkersAgent<C>(binding, key, wire, keyCodec);
  }
  const state = registry.getOrCreate(key);
  return constructBundle(state);
}

// Events track, slice 0 (spine #936, ADR 0284): a publishing context's
// `deps.__eventsDispatch` hands its release-at-commit event batch to this
// context's own fan-out Durable Object (one namespace per publishing
// context — `idFromName` is passed a fixed key since the DO instance itself,
// not the id, is what scopes the fan-out to this publisher and gives it
// single-threaded per-publisher ordering). A non-`ok` response is logged, not
// thrown: the publishing handler already committed by the time this runs
// (release-at-commit), so a fan-out transport failure must not surface as a
// failure of the handler that emitted.
export async function dispatchToEventsFanout(
  binding: DurableObjectNamespace,
  events: Array<{
    type: string;
    payload: unknown;
    envelope: { eventId: string; publisherId: string; emittedAt: number; schemaVersion: number };
  }>,
): Promise<void> {
  // The whole round trip is wrapped, not just the status check: a rejected
  // `stub.fetch` (a network error, the DO throwing) is exactly as much a
  // fan-out transport failure as a non-`ok` response, and by this point
  // `commitState` has already succeeded — letting a rejection propagate
  // would surface a transport problem as a failure of a handler that, from
  // the caller's perspective, already completed.
  try {
    const stub = binding.get(binding.idFromName("singleton"));
    const response = await stub.fetch("https://_bynk/_bynk/fanout", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ events }),
    });
    if (!response.ok) {
      console.error("EventsFanout dispatch failed", { status: response.status });
    }
  } catch (e) {
    console.error("EventsFanout dispatch failed", { error: String(e) });
  }
}

// v0.16: an in-process Durable-Object namespace for multi-Worker integration
// tests. `cls` is the emitted DO class, built from a fresh in-memory state;
// one instance is kept per key (so state accumulates within a test case). The
// returned stub bridges the stub-side `fetch(url, init)` the agent runtime
// speaks to the DO class's server-side `fetch(request)`.
//
// #1959: the class is constructed with `(state, env)` as workerd does, so an
// agent that rebuilds `given` deps or emits events from `env`, and the events
// fan-out, see the participant's bindings. A class whose constructor takes
// only `state` still fits this type: a constructor with fewer parameters is
// assignable to one with more.
export function makeIntegrationDoNamespace(
  cls: new (state: DurableObjectState, env?: unknown) => {
    fetch(request: Request): Promise<Response>;
  },
  env?: unknown,
): DurableObjectNamespace {
  const instances = new Map<string, { fetch(request: Request): Promise<Response> }>();
  return {
    idFromName(name: string): unknown {
      return name;
    },
    get(id: unknown): DurableObjectStub {
      const k = String(id);
      let inst = instances.get(k);
      if (inst === undefined) {
        inst = new cls(makeTestState(k), env);
        instances.set(k, inst);
      }
      const target = inst;
      return {
        fetch: (input: string, init?: unknown): Promise<Response> =>
          target.fetch(new Request(input, init as RequestInit)),
      };
    },
  };
}

// State-migrations S4 (#2259 Decision D): `bynk migrate sweep`'s wake.
//
// The Worker side. `body` is the verified request body, `{ "ids": [...] }`,
// each a Durable Object id from Cloudflare's objects listing. Every id is
// woken through the reserved `/_bynk/migrate` entry, which loads the
// instance's state (running any migration step) and commits it when it was
// older than `current`. The answer is `{ current, results }`: `current` is
// the version this deployed Worker writes, which the sweep needs even for a
// namespace with no instances, and `results` holds each id's
// `{ id, before, after }` or `{ id, fault }`. One id's fault never stops the
// others.
export interface MigrationNamespace {
  idFromString(id: string): unknown;
  get(id: unknown): DurableObjectStub;
}

export const MIGRATION_MAX_IDS = 1000;

export async function sweepAgentInstances(
  binding: MigrationNamespace,
  body: string,
  current: number,
): Promise<Response> {
  let ids: unknown;
  try {
    ids = (JSON.parse(body) as { ids?: unknown } | null)?.ids;
  } catch {
    ids = undefined;
  }
  if (
    !Array.isArray(ids) ||
    ids.length > MIGRATION_MAX_IDS ||
    !ids.every((id) => typeof id === "string")
  ) {
    return new Response("Bad Request", { status: 400 });
  }
  const results = await Promise.all(
    (ids as string[]).map(async (id) => {
      let stub: DurableObjectStub;
      try {
        stub = binding.get(binding.idFromString(id));
      } catch {
        return { id, fault: "BadId" };
      }
      try {
        const response = await stub.fetch("https://_bynk/_bynk/migrate", { method: "POST" });
        if (!response.ok) return { id, fault: `Status${response.status}` };
        return { id, ...((await response.json()) as object) };
      } catch {
        return { id, fault: "Unreachable" };
      }
    }),
  );
  return new Response(JSON.stringify({ current, results }), {
    status: 200,
    headers: { "content-type": "application/json" },
  });
}

// The Durable Object side, the whole of its `/_bynk/migrate` entry. `stored`
// is the raw record under the state key (`undefined` when there is none). An
// absent `__v` is version 1, as `checkStoredSchemaVersion` reads it. `load`
// is the class's `loadState`, which checks the marker and runs any step;
// `commit` is its `commitState`, which runs the invariant gate and stamps
// `current`. A record already at `current` is read and not written. A fault
// is reported by kind only: never its detail, which can carry stored data.
export async function wakeForMigration<S>(
  stored: unknown,
  current: number,
  load: () => Promise<S>,
  commit: (state: S) => Promise<void>,
): Promise<Response> {
  const json = (value: object) =>
    new Response(JSON.stringify(value), {
      status: 200,
      headers: { "content-type": "application/json" },
    });
  if (stored === undefined || stored === null) return json({ before: null, after: null });
  const raw = typeof stored === "object" ? (stored as { readonly __v?: unknown }).__v : undefined;
  const marker = raw === undefined ? 1 : raw;
  const before = typeof marker === "number" ? marker : null;
  try {
    const state = await load();
    if (before === null || before < current) await commit(state);
    return json({ before, after: current });
  } catch (e) {
    return json({ before, fault: migrationFaultKind(e) });
  }
}

function migrationFaultKind(e: unknown): string {
  if (typeof e === "object" && e !== null) {
    const rehydration = (e as { rehydrationViolation?: { detail?: { kind?: unknown } } })
      .rehydrationViolation;
    if (rehydration !== undefined) {
      const kind = rehydration.detail?.kind;
      return typeof kind === "string" ? kind : "RehydrationViolation";
    }
    if ((e as { invariantViolation?: unknown }).invariantViolation !== undefined) {
      return "InvariantViolation";
    }
  }
  return "Fault";
}

// v0.47: Bearer-token verification (the actors slice-2 seam). Verifies a JWT's
// HS256 signature against `secret` using WebCrypto (constant-time
// `crypto.subtle.verify`), enforces `exp`/`nbf`, and returns the `sub` claim.
// Any failure is an `Err` the caller maps to 401 — fail-closed. The raw token
// never leaves this function; only the verified `sub` flows out.
function __bynkB64UrlToBytes(s: string): Uint8Array {
  const b64 = s.replace(/-/g, "+").replace(/_/g, "/").padEnd(Math.ceil(s.length / 4) * 4, "=");
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export async function verifyBearerJwtHs256(
  token: string,
  secret: string,
): Promise<Result<{ readonly sub: string; readonly claims: Record<string, unknown> }, string>> {
  const parts = token.split(".");
  if (parts.length !== 3) return Err("malformed token");
  const [headerB64, payloadB64, sigB64] = parts;
  let header: { alg?: unknown };
  try {
    header = JSON.parse(new TextDecoder().decode(__bynkB64UrlToBytes(headerB64)));
  } catch {
    return Err("malformed header");
  }
  // Reject algorithm confusion / `alg: none` — this seam only verifies HS256.
  if (header.alg !== "HS256") return Err("unsupported alg");
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    enc.encode(secret) as BufferSource,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["verify"],
  );
  let ok: boolean;
  try {
    ok = await crypto.subtle.verify(
      "HMAC",
      key,
      __bynkB64UrlToBytes(sigB64) as BufferSource,
      enc.encode(`${headerB64}.${payloadB64}`) as BufferSource,
    );
  } catch {
    return Err("verify failed");
  }
  if (!ok) return Err("bad signature");
  let payload: { sub?: unknown; exp?: unknown; nbf?: unknown };
  try {
    payload = JSON.parse(new TextDecoder().decode(__bynkB64UrlToBytes(payloadB64)));
  } catch {
    return Err("malformed payload");
  }
  const now = Math.floor(Date.now() / 1000);
  // RFC 7519: `exp`/`nbf` are NumericDate (a number). `exp` is required — a
  // token with no expiry never ages out, so a leaked bearer cannot be revoked
  // by time; parity with the OIDC seam below. A present-but-non-number `exp`
  // (or `nbf`) is malformed — reject rather than silently skip the time check.
  if (payload.exp === undefined) return Err("missing exp");
  if (typeof payload.exp !== "number") return Err("malformed exp");
  if ((payload.exp as number) < now) return Err("token expired");
  if (payload.nbf !== undefined && typeof payload.nbf !== "number") return Err("malformed nbf");
  if (payload.nbf !== undefined && (payload.nbf as number) > now) return Err("token not yet valid");
  if (typeof payload.sub !== "string" || payload.sub.length === 0) return Err("missing sub");
  // v0.53: surface the full verified claims for refinement-actor authorisation
  // (`actor Admin = User where hasClaim(...)`). The identity stays `sub`-minted
  // and sealed; claims are an authorisation-time input, checked at the boundary.
  return Ok({ sub: payload.sub, claims: payload as Record<string, unknown> });
}

// v0.51: Signature (webhook) verification — recompute an HMAC-SHA256 over the
// raw body (or `<timestamp>.<body>` when a timestamp is bound) and compare it,
// constant-time (`crypto.subtle.verify`), against the request's signature
// header (accepting a `sha256=<hex>` prefix or a bare hex digest). When a
// timestamp is bound, it is signed (so it cannot be forged) and checked within
// `toleranceSecs` for replay defence. Returns `true` iff the request is
// authentic; the caller maps `false` to 401. The body never reaches the handler
// unverified.
function __bynkHexToBytes(hex: string): Uint8Array {
  const clean = hex.startsWith("sha256=") ? hex.slice(7) : hex;
  if (clean.length === 0 || clean.length % 2 !== 0 || /[^0-9a-fA-F]/.test(clean)) {
    return new Uint8Array(0);
  }
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  return out;
}

export async function verifySignatureHmacSha256(
  body: string | Uint8Array,
  secret: string,
  signatureHeader: string | null,
  timestamp: string | null,
  toleranceSecs: number | null,
): Promise<boolean> {
  if (signatureHeader === null) return false;
  // When a timestamp is bound it is part of the signed string (so it cannot be
  // forged); a tolerance, if set, bounds replay.
  // A `@raw` route signs the octets as received (`Uint8Array`), a JSON route
  // the text read from them (`string`); the timestamp prefix is the same bytes
  // either way.
  const enc = new TextEncoder();
  let signed: Uint8Array = typeof body === "string" ? enc.encode(body) : body;
  if (timestamp !== null) {
    const ts = Number(timestamp);
    if (!Number.isFinite(ts)) return false;
    if (toleranceSecs !== null) {
      const now = Math.floor(Date.now() / 1000);
      if (Math.abs(now - ts) > toleranceSecs) return false;
    }
    if (typeof body === "string") {
      signed = enc.encode(`${timestamp}.${body}`);
    } else {
      const prefix = enc.encode(`${timestamp}.`);
      signed = new Uint8Array(prefix.length + body.length);
      signed.set(prefix, 0);
      signed.set(body, prefix.length);
    }
  }
  const sigBytes = __bynkHexToBytes(signatureHeader);
  if (sigBytes.length === 0) return false;
  const key = await crypto.subtle.importKey(
    "raw",
    enc.encode(secret) as BufferSource,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["verify"],
  );
  try {
    return await crypto.subtle.verify(
      "HMAC",
      key,
      sigBytes as BufferSource,
      signed as BufferSource,
    );
  } catch {
    return false;
  }
}

// v0.151: OIDC/JWKS verification (the actors OIDC slice). Verifies an
// asymmetrically-signed JWT (RS256 or ES256) against the provider's published
// key set: fetch the JWKS (cached, refetched once on a `kid` miss so key
// rotation heals without a redeploy), import the matching public key via
// WebCrypto, verify the signature (`crypto.subtle.verify`), then enforce the
// trust contract — `iss` equals the declared issuer, `aud` contains the
// declared audience, `exp` is present and in the future, `nbf` (if present) has
// passed — and return the `sub` claim. Any failure is an `Err` the caller maps
// to 401 — fail-closed. Unlike the Bearer/Signature seams there is **no shared
// secret**: the trust root is the provider's public JWKS. `alg: none` and
// symmetric algorithms (HS*) are rejected — a symmetric alg against a public
// key is the classic algorithm-confusion forgery.
type __BynkJwk = JsonWebKey & { kid?: string; alg?: string; use?: string };

interface __BynkJwksCacheEntry {
  keys: __BynkJwk[];
  /** When `keys` were last successfully fetched — the TTL basis. */
  fetchedAt: number;
  /** When the network was last hit (success or failure) — the refetch-cooldown
   *  basis; bounds `kid`-miss refetch amplification. */
  lastAttemptAt: number;
}

const __bynkJwksCache = new Map<string, __BynkJwksCacheEntry>();
const __BYNK_JWKS_TTL_MS = 10 * 60 * 1000;
// A forced (`kid`-miss) refetch is rate-limited to at most once per this window
// per URI. `kid` is attacker-controlled and not integrity-protected before
// verification, so without a cooldown an unauthenticated caller could drive one
// uncached JWKS fetch per request just by varying `kid`. Mirrors `jose`'s
// `cooldownDuration`.
const __BYNK_JWKS_REFETCH_COOLDOWN_MS = 30 * 1000;
// Clock-skew leeway (seconds) applied to `exp`/`nbf`.
const __BYNK_CLOCK_SKEW_S = 60;

async function __bynkFetchJwks(jwksUri: string, force: boolean): Promise<__BynkJwk[] | null> {
  const now = Date.now();
  const cached = __bynkJwksCache.get(jwksUri);
  if (cached !== undefined) {
    // A normal read serves cached keys within the TTL.
    if (!force && now - cached.fetchedAt < __BYNK_JWKS_TTL_MS) return cached.keys;
    // A forced (`kid`-miss) refetch is skipped while within the cooldown, so a
    // flood of forged tokens with novel `kid`s cannot amplify into fetches.
    if (force && now - cached.lastAttemptAt < __BYNK_JWKS_REFETCH_COOLDOWN_MS) return cached.keys;
    // Record this attempt up front so a concurrent/subsequent forced call (or a
    // fetch that then fails) still honours the cooldown.
    cached.lastAttemptAt = now;
  }
  let res: Response;
  try {
    res = await fetch(jwksUri);
  } catch {
    return cached?.keys ?? null;
  }
  if (!res.ok) return cached?.keys ?? null;
  let body: { keys?: unknown };
  try {
    body = (await res.json()) as { keys?: unknown };
  } catch {
    return cached?.keys ?? null;
  }
  if (!Array.isArray(body.keys)) return cached?.keys ?? null;
  const keys = body.keys as __BynkJwk[];
  __bynkJwksCache.set(jwksUri, { keys, fetchedAt: now, lastAttemptAt: now });
  return keys;
}

function __bynkAlgParams(alg: string): {
  importAlg: RsaHashedImportParams | EcKeyImportParams;
  verifyAlg: AlgorithmIdentifier | EcdsaParams;
  kty: string;
} | null {
  if (alg === "RS256") {
    return {
      importAlg: { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
      verifyAlg: "RSASSA-PKCS1-v1_5",
      kty: "RSA",
    };
  }
  if (alg === "ES256") {
    return {
      importAlg: { name: "ECDSA", namedCurve: "P-256" },
      verifyAlg: { name: "ECDSA", hash: "SHA-256" },
      kty: "EC",
    };
  }
  return null;
}

export async function verifyOidcJwt(
  token: string,
  issuer: string,
  audience: string,
  jwksUri: string,
): Promise<Result<{ readonly sub: string; readonly claims: Record<string, unknown> }, string>> {
  const parts = token.split(".");
  if (parts.length !== 3) return Err("malformed token");
  const [headerB64, payloadB64, sigB64] = parts;
  let header: { alg?: unknown; kid?: unknown };
  try {
    header = JSON.parse(new TextDecoder().decode(__bynkB64UrlToBytes(headerB64)));
  } catch {
    return Err("malformed header");
  }
  // Only asymmetric OIDC signing algorithms — reject `none`, HS* (symmetric,
  // algorithm-confusion against the public key), and anything unlisted.
  if (typeof header.alg !== "string") return Err("missing alg");
  const params = __bynkAlgParams(header.alg);
  if (params === null) return Err("unsupported alg");
  const kid = typeof header.kid === "string" ? header.kid : null;

  const enc = new TextEncoder();
  const signed = enc.encode(`${headerB64}.${payloadB64}`) as BufferSource;
  const sig = __bynkB64UrlToBytes(sigB64) as BufferSource;

  // Try each candidate key (matched by `kid` when the header names one, else by
  // key type). `hadCandidate` distinguishes a `kid` miss — a refetch may heal a
  // key rotation — from a genuine bad signature against a published key, which
  // never refetches. The `kid`-miss refetch is itself rate-limited by the
  // cooldown in `__bynkFetchJwks` (a novel `kid` is attacker-controlled).
  const attempt = async (keys: __BynkJwk[]): Promise<{ verified: boolean; hadCandidate: boolean }> => {
    const candidates = keys.filter(
      (k) =>
        k.kty === params.kty &&
        (k.use === undefined || k.use === "sig") &&
        (kid === null || k.kid === undefined || k.kid === kid),
    );
    for (const jwk of candidates) {
      let key: CryptoKey;
      try {
        key = await crypto.subtle.importKey("jwk", jwk, params.importAlg, false, ["verify"]);
      } catch {
        continue;
      }
      try {
        if (await crypto.subtle.verify(params.verifyAlg, key, sig, signed)) {
          return { verified: true, hadCandidate: true };
        }
      } catch {
        // treat an import/verify throw as a non-match and keep trying
      }
    }
    return { verified: false, hadCandidate: candidates.length > 0 };
  };

  const keys = await __bynkFetchJwks(jwksUri, false);
  if (keys === null) return Err("jwks unavailable");
  let verified = false;
  const first = await attempt(keys);
  verified = first.verified;
  if (!verified && !first.hadCandidate) {
    const refetched = await __bynkFetchJwks(jwksUri, true);
    if (refetched !== null) verified = (await attempt(refetched)).verified;
  }
  if (!verified) return Err("bad signature");

  let payload: { sub?: unknown; iss?: unknown; aud?: unknown; exp?: unknown; nbf?: unknown };
  try {
    payload = JSON.parse(new TextDecoder().decode(__bynkB64UrlToBytes(payloadB64)));
  } catch {
    return Err("malformed payload");
  }
  // Issuer and audience are the trust contract — a token from another issuer or
  // for another audience is rejected even though its signature is authentic.
  if (payload.iss !== issuer) return Err("issuer mismatch");
  const audOk =
    payload.aud === audience ||
    (Array.isArray(payload.aud) && (payload.aud as unknown[]).includes(audience));
  if (!audOk) return Err("audience mismatch");
  const now = Math.floor(Date.now() / 1000);
  // A small leeway absorbs clock skew between this Worker and the issuer, so a
  // valid token is not spuriously rejected at the second boundary (RFC 7519
  // permits "some small leeway, usually no more than a few minutes").
  const skew = __BYNK_CLOCK_SKEW_S;
  // OIDC tokens carry an `exp`; a missing/non-number one is malformed, not a
  // token that never expires.
  if (typeof payload.exp !== "number") return Err("missing exp");
  if ((payload.exp as number) < now - skew) return Err("token expired");
  if (payload.nbf !== undefined && typeof payload.nbf !== "number") return Err("malformed nbf");
  if (payload.nbf !== undefined && (payload.nbf as number) > now + skew) return Err("token not yet valid");
  if (typeof payload.sub !== "string" || payload.sub.length === 0) return Err("missing sub");
  return Ok({ sub: payload.sub, claims: payload as Record<string, unknown> });
}

// v0.102 (real-time track slice 2): the runtime contract for a held
// `Connection[F]`. A `Connection<F>` is a typed handle to a long-lived channel;
// `send` writes a server→client frame, `close` ends the connection. The
// concrete implementations — a capture-and-inspect `TestConnection` for the
// bundle/test target and the hibernatable-WebSocket binding for Workers — arrive
// with the `from WebSocket` protocol (slice 3); the language emits against this
// interface, and the linearity discipline (§2.9) governs ownership at the type
// level.

export interface Connection<F> {
  send(frame: F): Promise<void>;
  close(): Promise<void>;
}

// v0.103: the bundle/test realisation of a `Connection[F]` — a capture-and-inspect
// channel. The runtime-managed lifecycle in production becomes an inspectable
// record in tests (design notes §20): `sent` holds every frame `send`-given, and
// `closed` records disposal. A test drives an `on open` handler with a
// `TestConnection` and asserts what the agent sent.
export class TestConnection<F> implements Connection<F> {
  readonly sent: F[] = [];
  closed = false;

  async send(frame: F): Promise<void> {
    if (this.closed) throw new Error("send on a closed TestConnection");
    this.sent.push(frame);
  }

  async close(): Promise<void> {
    this.closed = true;
  }
}

// v0.104/v0.105 (real-time track slice 3b): the Cloudflare Workers realisation of
// a `Connection[F]`, wrapping a server-side `WebSocket` accepted in a Durable
// Object. A frame is sent as JSON; `close` ends the socket. The `connId` is the
// hibernation tag the socket was accepted under (slice 3b-ii): a stored connection
// persists this id, and `resolveConnection` re-presents the live socket by it
// after the DO wakes — so the held value survives eviction (§2.9.6).
export class WorkersConnection<F> implements Connection<F> {
  // Explicit fields + assignment, not constructor parameter properties — Node's
  // `--experimental-strip-types` (the `--inspect` debug path runs the emitted `.ts`
  // directly) rejects parameter properties, which are not erasable.
  private readonly ws: { send(data: string): void; close(): void };
  readonly connId: string;

  constructor(ws: { send(data: string): void; close(): void }, connId: string) {
    this.ws = ws;
    this.connId = connId;
  }

  async send(frame: F): Promise<void> {
    this.ws.send(JSON.stringify(frame));
  }

  async close(): Promise<void> {
    this.ws.close();
  }
}

// v0.105 (slice 3b-ii): the connection id a held `Connection` persists. The stored
// value is this string, not the live socket (which cannot be serialised); the
// socket is re-resolved per access via `resolveConnection`.
export function connIdOf(conn: Connection<unknown>): string {
  return (conn as WorkersConnection<unknown>).connId;
}

// v0.104 (real-time track slice 3b): the minimal structural surface of a
// Cloudflare server-side `WebSocket`, so emitted Worker code type-checks under
// `tsc --strict` without depending on `@cloudflare/workers-types`. The real
// runtime object is richer but compatible.
export interface WorkersWebSocket {
  accept(): void;
  send(data: string): void;
  close(code?: number, reason?: string): void;
  // v0.105 (slice 3b-ii): hibernation attachment — small per-socket data the
  // platform preserves across hibernation (the connId, so a waking dispatch can
  // recover it without loading durable state).
  serializeAttachment(value: unknown): void;
  deserializeAttachment(): unknown;
}

// v0.105 (slice 3b-ii): the Durable Object's hibernatable-WebSocket surface.
// `acceptWebSocket(ws, tags)` accepts a server socket so it survives the DO's
// hibernation (unlike `ws.accept()`); `getWebSockets(tag)` re-presents the
// accepted sockets (by tag) when the DO wakes. Narrowly typed and reached by a
// cast so the shared `DurableObjectState` (and the bundle `makeTestState`) need
// not carry the API.
interface HibernatableState {
  acceptWebSocket(ws: WorkersWebSocket, tags?: string[]): void;
  getWebSockets(tag?: string): WorkersWebSocket[];
}

// Accept a server socket into the DO under a fresh connection id (the hibernation
// tag), attach the id for wake-time recovery, and wrap it. The returned
// `WorkersConnection` carries the connId a held store persists.
export function acceptHibernatableConnection<F>(
  state: DurableObjectState,
  server: WorkersWebSocket,
  // v0.106 (slice 3b-iii): when the service has an inbound/close handler, the
  // sender identity + route args are attached too, so a waking `webSocketMessage`/
  // `webSocketClose` recovers them (the `on open` already authenticated the actor).
  meta?: Record<string, unknown>,
): WorkersConnection<F> {
  const connId = crypto.randomUUID();
  (state as unknown as HibernatableState).acceptWebSocket(server, [connId]);
  server.serializeAttachment(meta === undefined ? { connId } : { connId, ...meta });
  return new WorkersConnection<F>(server, connId);
}

// Re-present the live socket a stored connId names, re-wrapped as a
// `WorkersConnection`. `None` when the platform has no such socket — a connection
// that has since closed (normal lifecycle, not corruption).
export function resolveConnection<F>(
  state: DurableObjectState,
  connId: string,
): Option<WorkersConnection<F>> {
  const sockets = (state as unknown as HibernatableState).getWebSockets(connId);
  const ws = sockets[0];
  return ws === undefined ? None : Some(new WorkersConnection<F>(ws, connId));
}

export interface WorkersWebSocketPair {
  client: WorkersWebSocket;
  server: WorkersWebSocket;
}

// Construct a Cloudflare `WebSocketPair` (a Workers runtime global), returned as
// a named `{ client, server }` pair. The pair is index-shaped at runtime
// (`pair[0]` = client, `pair[1]` = server); this normalises it and keeps the
// global access in one place so emitted code stays free of ambient declarations.
export function newWebSocketPair(): WorkersWebSocketPair {
  const Ctor = (globalThis as { WebSocketPair?: new () => { 0: WorkersWebSocket; 1: WorkersWebSocket } })
    .WebSocketPair;
  if (Ctor === undefined) {
    throw new Error("WebSocketPair is not available in this runtime");
  }
  const pair = new Ctor();
  return { client: pair[0], server: pair[1] };
}

// Build the `101 Switching Protocols` response that hands the client end of an
// accepted `WebSocketPair` back to the caller — the Cloudflare upgrade
// completion. `webSocket` is a Workers-specific `ResponseInit` extension.
export function webSocketUpgradeResponse(client: WorkersWebSocket): Response {
  return new Response(null, { status: 101, webSocket: client } as ResponseInit & {
    webSocket: WorkersWebSocket;
  });
}

// message-bundles slice 3 (#878): ICU MessageFormat formatting helpers.
// Delegate entirely to the host JS engine's own `Intl` object — no CLDR
// data is bundled here (Decision A). Emitted `messages`-bundle code calls
// these directly; see `bynk-emit/src/emitter/emit.rs`'s `emit_icu_placeholder`.

/**
 * Selects a plural category's arm using the host `Intl.PluralRules` for
 * `tag`. Falls back to `"other"` if `Intl.PluralRules` selects a category
 * `arms` doesn't declare — the checker (`bynk.messages.malformed_icu_syntax`)
 * already guarantees every declared `plural` placeholder has an `other` arm,
 * so `arms["other"]` is always defined; this is a real runtime fallback (a
 * locale's actual CLDR category set can differ from the arms an author
 * happened to write), not dead code.
 *
 * The `?? arms["other"]` here is safe where the emitted `select` dispatch's
 * was not (#900): `category` comes from `Intl.PluralRules().select()`, whose
 * return is closed over `zero|one|two|few|many|other` — none an
 * `Object.prototype` member — so it can never resolve off the prototype chain.
 * A `select` arm, by contrast, is keyed by an arbitrary runtime `MessageArg`
 * value and needs an own-property (`Object.hasOwn`) check instead.
 */
export function selectPluralArm(
  tag: string,
  n: number,
  arms: Record<string, string>,
): string {
  const category = new Intl.PluralRules(tag).select(n);
  return arms[category] ?? arms["other"];
}

export function formatIcuNumber(
  tag: string,
  n: number,
  style?: "integer" | "percent",
): string {
  const options: Intl.NumberFormatOptions =
    style === "integer"
      ? { maximumFractionDigits: 0 }
      : style === "percent"
        ? { style: "percent" }
        : {};
  return new Intl.NumberFormat(tag, options).format(n);
}

export function formatIcuDate(
  tag: string,
  epochMillis: number,
  style?: "short" | "medium" | "long" | "full",
): string {
  const options: Intl.DateTimeFormatOptions =
    style !== undefined ? { dateStyle: style } : {};
  return new Intl.DateTimeFormat(tag, options).format(new Date(epochMillis));
}

// Locale capability track, slice 2 (#882): RFC 4647 basic filtering of an
// `Accept-Language` header against a bundle's declared locale set — exact
// match, then successive rightmost-subtag truncation (`pt-BR` -> `pt`),
// falling back to the bundle's reference locale. Total: never throws, and
// always returns either a member of `declared` or `reference` verbatim
// (both already-valid `LocaleTag`s the compiler itself emitted), never a
// derived string of its own.

export function negotiateLocale(
  header: string | null | undefined,
  declared: readonly string[],
  reference: string,
): string {
  if (!header) return reference;
  const ranges = header
    .split(",")
    .map((part) => {
      const [rangeRaw, ...params] = part.split(";");
      const range = rangeRaw.trim();
      let q = 1;
      for (const param of params) {
        const [k, v] = param.trim().split("=");
        if (k === "q") {
          const n = Number(v);
          if (Number.isFinite(n)) q = n;
        }
      }
      return { range, q };
    })
    .filter((r) => r.range.length > 0 && r.range !== "*")
    // Array.prototype.sort is spec-guaranteed stable, so equal-q ranges keep
    // the header's own left-to-right preference order.
    .sort((a, b) => b.q - a.q);

  const declaredLower = declared.map((d) => d.toLowerCase());
  for (const { range } of ranges) {
    let candidate = range.toLowerCase();
    while (candidate.length > 0) {
      const idx = declaredLower.indexOf(candidate);
      if (idx !== -1) return declared[idx];
      const lastDash = candidate.lastIndexOf("-");
      if (lastDash === -1) break;
      candidate = candidate.slice(0, lastDash);
    }
  }
  return reference;
}

// #1653: every runtime name an emitted module imports is also exported under
// a `__` alias, and emitted code imports only the alias. A Bynk identifier
// cannot start with `_`, so no user type, function or binding in the
// importing module can collide with an imported runtime name (a user
// `type JsonValue` beside an import of `JsonValue` would not compile).
// The plain names stay exported for the runtime's own tests.

